fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut lines = input.lines();
    let mut first_line = lines.next().unwrap().split_whitespace();
    let n: usize = first_line.next().unwrap().parse().unwrap();
    let l: usize = first_line.next().unwrap().parse().unwrap();
    let r: usize = first_line.next().unwrap().parse().unwrap();

    let mut dd: Vec<i32> = vec![0; n + 1];
    let mut d2: Vec<i32> = vec![0; n + 1];
    let mut flag: Vec<bool> = vec![false; n + 1];

    for (i, val) in lines.next().unwrap().split_whitespace().enumerate() {
        dd[i + 1] = val.parse().unwrap();
    }
    for (i, val) in lines.next().unwrap().split_whitespace().enumerate() {
        d2[i + 1] = val.parse().unwrap();
    }

    for i in 1..l {
        if dd[i] != d2[i] {
            println!("LIE");
            return;
        }
    }
    for i in r + 1..=n {
        if dd[i] != d2[i] {
            println!("LIE");
            return;
        }
    }
    for i in l..=r {
        flag[dd[i] as usize] = true;
    }
    for i in l..=r {
        if !flag[d2[i] as usize] {
            println!("LIE");
            return;
        }
    }
    println!("TRUTH");
}

