use std::cmp::Ordering;
use std::io::{self, BufRead};

fn main() {
    let stdin = io::stdin();
    let mut lines = stdin.lock().lines().map(|l| l.unwrap());

    let a = lines.next().unwrap();
    let b = lines.next().unwrap();

    let na: String = a.chars().skip_while(|&c| c == '0').collect();
    let nb: String = b.chars().skip_while(|&c| c == '0').collect();

    match na.len().cmp(&nb.len()) {
        Ordering::Greater => println!(">"),
        Ordering::Less => println!("<"),
        Ordering::Equal => {
            match na.chars().zip(nb.chars()).find(|(c1, c2)| c1 != c2) {
                Some((c1, c2)) => println!("{}", if c1 > c2 { ">" } else { "<" }),
                None => println!("="),
            }
        }
    }
}

