        let p = x - yy;
        output += (y - x) * p1;
        output += match p {
            p if p <= t1 => p * p1,
            p if p <= t1 + t2 => p1 * t1 + (p - t1) * p2,
            _ => p1 * t1 + p2 * t2 + (p - t1 - t2) * p3,
        };
    }

