fn main() -> io::Result<()> {
    let input = io::BufReader::new(io::stdin());
    let mut lines = input.lines();
    let mut output = io::BufWriter::new(io::stdout());

    let n: usize = lines.next().unwrap()?.parse().unwrap();
    let mut pos = vec![0; 1_000_005];
    let mut l = vec![0; 100_005];
    let mut r = vec![0; 100_005];
    let mut f = vec![0; 100_005];
    let mut min = 1_000_005;
    let mut max = 0;
    let mut index = 1;
    let mut ans = 0;

    for (i, line) in lines.take(n).enumerate() {
        let j: usize = line?.parse().unwrap();
        let i = i + 1;

        if pos[j] == 0 {
            pos[j] = index;
            index += 1;
            l[pos[j]] = i;
            r[pos[j]] = i;
            f[pos[j]] = 1;
        } else {
            r[pos[j]] = i;
            f[pos[j]] += 1;
        }

        if f[pos[j]] > max {
            max = f[pos[j]];
            min = r[pos[j]] - l[pos[j]];
            ans = pos[j];
        } else if f[pos[j]] == max {
            if min > (r[pos[j]] - l[pos[j]]) {
                min = r[pos[j]] - l[pos[j]];
                ans = pos[j];
            }
        }
    }

    writeln!(output, "{} {}", l[ans], r[ans])?;
    Ok(())
}

