use std::cmp::Ordering;
use std::fs::File;
use std::io::{self, BufRead, BufReader, BufWriter, Write};
use std::str;

const MAX: usize = 100005;

fn main() -> io::Result<()> {
    let input = File::open("input.txt")?;
    let reader = BufReader::new(input);
    let output = File::create("myfile.txt")?;
    let mut writer = BufWriter::new(output);

    let mut lines = reader.lines();
    let n: usize = lines.next().unwrap()?.parse().unwrap();

    let mut f_name = vec![String::with_capacity(60); MAX];
    let mut l_name = vec![String::with_capacity(60); MAX];
    let mut p = vec![0; MAX];

    for i in 0..n {
        let line = lines.next().unwrap()?;
        let parts: Vec<&str> = line.split_whitespace().collect();
        f_name[i].push_str(parts[0]);
        l_name[i].push_str(parts[1]);
    }

    for i in 0..n {
        p[i] = lines.next().unwrap()?.parse().unwrap();
        p[i] -= 1;
    }

    let mut test = true;
    let mut choto = String::with_capacity(60);
    let mut boro = String::with_capacity(60);

    match f_name[p[0]].cmp(&l_name[p[0]]) {
        Ordering::Less => (),
        _ => f_name[p[0]] = l_name[p[0]].clone(),
    }

    for i in 1..n {
        match f_name[p[i]].cmp(&l_name[p[i]]) {
            Ordering::Less => {
                choto.clear();
                choto.push_str(&f_name[p[i]]);
                boro.clear();
                boro.push_str(&l_name[p[i]]);
            }
            _ => {
                boro.clear();
                boro.push_str(&f_name[p[i]]);
                choto.clear();
                choto.push_str(&l_name[p[i]]);
            }
        }

        match f_name[p[i - 1]].cmp(&choto) {
            Ordering::Less => f_name[p[i]] = choto.clone(),
            _ => match f_name[p[i - 1]].cmp(&boro) {
                Ordering::Less => f_name[p[i]] = boro.clone(),
                _ => {
                    test = false;
                    break;
                }
            },
        }
    }

    if test {
        writeln!(writer, "YES")?;
    } else {
        writeln!(writer, "NO")?;
    }

    Ok(())
}

