        let num: i32 = input.trim().parse().expect("Please type a number!");
        arr.push(num);
    }

    let (even, odd) = arr.iter().fold((0, 0), |(even, odd), &num| {
        if num % 2 == 0 {
            (even + 1, odd)
        } else {
            (even, odd + 1)
        }
    });

    let result = if even >= odd { odd } else { even };
    println!("{}", result);
}

