	static int aa[26];
	static int dp[N + 1];
	int n, i, j, max, cnt;

	scanf("%d", &n);
	scanf("%s", s);
	for (i = 0; i < 26; i++)
		scanf("%d", &aa[i]);
	max = 0;
	dp[0] = 1;
	for (i = 0; i < n; i++) {
		int min = aa[s[i] - 'a'];

		for (j = i + 1; j <= n && (min == INT_MAX || j <= i + min); j++) {
			if (j < n) {
				int c = s[j] - 'a';

				if (min > aa[c])
					min = aa[c];
			}
			if (max < j - i)
				max = j - i;
			dp[j] = (dp[j] + dp[i]) % MOD;
		}
	}
	cnt = 0;
	for (i = 0; i < n; ) {
		int min = aa[s[i] - 'a'];

		j = i;
		while (j < n && j < i + min) {
			if (j + 1 < n) {
				int c = s[j + 1] - 'a';

				if (min > aa[c])
					min = aa[c];
			}
			j++;
		}
		i = j;
		cnt++;
	}
