    let mut dp = vec![0; N + 1];
    dp[0] = 1;
    let mut max = 0;

    for i in 0..n {
        let mut min = aa[(s[i] as u8 - b'a') as usize];
        for j in i + 1..=n {
            if j < n {
                let c = (s[j] as u8 - b'a') as usize;
                if min > aa[c] {
                    min = aa[c];
                }
            }
            if max < j - i {
                max = j - i;
            }
            if j <= n {
                dp[j] = (dp[j] + dp[i]) % MOD;
            }
            if j == n || j >= i + min as usize {
                break;
            }
        }
    }

    let mut cnt = 0;
    let mut i = 0;
    while i < n {
        let mut min = aa[(s[i] as u8 - b'a') as usize];
