        input.clear();
        io::stdin().read_line(&mut input)?;
        a[i] = input.trim().parse().unwrap();
    }

    for &value in &a[..n-1] {
        match value {
            0 => print!("R"),
            1 => print!("PR"),
            _ => {
                for _ in 1..value {
                    print!("PRL");
                }
                print!("PR");
            }
        }
    }

    match a[n-1] {
        0 => {}
        1 => print!("P"),
        _ => {
            for _ in 1..a[n-1] {
                print!("PLR");
            }
            print!("P");
        }
    }

    io::stdout().flush()?;
    Ok(())
