        } else if b > a && b > c {
            format!("{} 0 {}\n", b - a + 1, b - c + 1)
        } else if c > a && c > b {
            format!("{} {} 0\n", c - a + 1, c - b + 1)
        } else if a == b && b > c {
            format!("1 1 {}\n", b - c + 1)
        } else if a == c && a > b {
            format!("1 {} 1\n", c - b + 1)
        } else if b == c && b > a {
