use std::cmp::Ordering;
use std::io::{self, Write};

fn main() -> io::Result<()> {
    let mut input = String::new();
    io::stdin().read_line(&mut input)?;

    let mut parts = input.trim().split_whitespace();
    let str1 = parts.next().unwrap_or("");
    let str2 = parts.next().unwrap_or("");

    let l1 = str1.len();
    let l2 = str2.len();

    match l1.cmp(&l2) {
        Ordering::Greater => writeln!(io::stdout(), "{}", l1)?,
        Ordering::Less => writeln!(io::stdout(), "{}", l2)?,
        Ordering::Equal => {
            if str1 == str2 {
                writeln!(io::stdout(), "-1")?;
            } else {
                writeln!(io::stdout(), "{}", l1)?;
            }
        }
    }

    Ok(())
}

