    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace().map(|s| s.parse::<i32>().unwrap());

    let n = iter.next().unwrap();
    let m = iter.next().unwrap();
    let b = iter.next().unwrap();
    let mod_val = iter.next().unwrap();

    let mut mem = vec![vec![0; (b + 1) as usize]; (m + 1) as usize];
    mem[0][0] = 1;

    for _ in 0..n {
        let bs = iter.next().unwrap();
        for j in 0..=m-1 {
            for k in 0..=b-bs {
                mem[(j + 1) as usize][(k + bs) as usize] += mem[j as usize][k as usize];
                if mem[(j + 1) as usize][(k + bs) as usize] >= mod_val {
                    mem[(j + 1) as usize][(k + bs) as usize] -= mod_val;
                }
            }
        }
    }

    let ans: i32 = mem[m as usize].iter().sum::<i32>() % mod_val;
    println!("{}", ans);
}

