    let m: usize = parts.next().unwrap().parse().unwrap();

    let mut output = String::new();

    if m > 2 * (n + 1) || m < (n - 1) {
        output.push_str("-1");
    } else if m == (n - 1) {
        output.extend(std::iter::repeat("01").take(n - 1));
        output.push('0');
    } else if m == n || m == (n + 1) {
        output.extend(std::iter::repeat("10").take(n));
        if m == (n + 1) {
            output.push('1');
        }
    } else {
        let mut k = m - n - 1;
        for _ in 0..n {
            if k > 0 {
                output.push_str("110");
                k -= 1;
            } else {
                output.push_str("10");
            }
        }
        if k > 0 {
            output.push_str("11");
        } else {
            output.push('1');
        }
    }

    print!("{}", output);
    io::stdout().flush()?;
    Ok(())
}

