use std::io::{self, BufRead};

fn main() {
    let stdin = io::stdin();
    let mut lines = stdin.lock().lines().map(|l| l.unwrap());

    let n: usize = lines.next().unwrap().parse().unwrap();
    let mut a: Vec<(i64, i64)> = vec![(0, 0); n + 1];

    for i in 1..=n {
        let line = lines.next().unwrap();
        let parts: Vec<i64> = line.split_whitespace().map(|s| s.parse().unwrap()).collect();
        a[i] = (parts[0], parts[1]);
    }

    let mut count = 1;

    for i in 0..n {
        match (a[i].0.cmp(&a[i].1), a[i + 1].0.cmp(&a[i + 1].1)) {
            (std::cmp::Ordering::Greater, std::cmp::Ordering::Greater) => {
                if a[i + 1].1 == a[i].0 {
                    count += 1;
                } else if a[i + 1].1 > a[i].0 {
                    count += a[i + 1].1 - a[i].0 + 1;
                }
            }
            (std::cmp::Ordering::Greater, std::cmp::Ordering::Less | std::cmp::Ordering::Equal) => {
                count += a[i + 1].0 - a[i].0 + 1;
            }
            (std::cmp::Ordering::Equal, std::cmp::Ordering::Greater) => {
                count += a[i + 1].1 - a[i].0;
            }
            (std::cmp::Ordering::Equal, std::cmp::Ordering::Less | std::cmp::Ordering::Equal) => {
                count += a[i + 1].0 - a[i].0;
            }
            (std::cmp::Ordering::Less, std::cmp::Ordering::Greater) => {
                count += a[i + 1].1 - a[i].1 + 1;
            }
            (std::cmp::Ordering::Less, std::cmp::Ordering::Less | std::cmp::Ordering::Equal) => {
                if a[i + 1].0 == a[i].1 {
                    count += 1;
                } else if a[i + 1].0 > a[i].1 {
                    count += a[i + 1].0 - a[i].1 + 1;
                }
            }
        }
    }

    println!("{}", count);
}

