            while time > 0 {
                match time {
                    _ if time >= t1 => {
                        ans += t1 * p1;
                        time -= t1;
                    }
                    _ => {
                        ans += time * p1;
                        time = 0;
                    }
                }
                if time == 0 {
                    break;
                }
                match time {
                    _ if time >= t2 => {
                        ans += t2 * p2;
                        time -= t2;
                    }
                    _ => {
                        ans += time * p2;
                        time = 0;
                    }
                }
                if time == 0 {
