use std::io::{self, Write};

fn main() -> io::Result<()> {
    let mut input = String::new();
    io::stdin().read_line(&mut input)?;
    let n: usize = input.trim().parse().unwrap();

    let mut stdout = io::stdout();
    for i in (1..=n).step_by(2) {
        write_stars_and_ds(&mut stdout, n, i)?;
    }
    for i in (1..n).rev().step_by(2) {
        write_stars_and_ds(&mut stdout, n, i)?;
    }

    Ok(())
}

fn write_stars_and_ds(stdout: &mut impl Write, n: usize, i: usize) -> io::Result<()> {
    let stars = (n - i) / 2;
    write!(stdout, "{}", "*".repeat(stars))?;
    write!(stdout, "{}", "D".repeat(i))?;
    write!(stdout, "{}\n", "*".repeat(stars))?;
    Ok(())
}

