const N: usize = 100000;
const MD: u64 = 1000000007;

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let s = input.trim_end().as_bytes();
    let n = s.len();

    let mut ff = vec![0; N + 1];
    ff[0] = 1;
    ff[1] = 1;
    for i in 2..=n {
        ff[i] = (ff[i - 1] + ff[i - 2]) % MD;
    }

    if s.iter().any(|&c| c == b'w' || c == b'm') {
        println!("0");
        return;
    }

    let mut ans = 1;
    let mut i = 0;
    while i < n {
        if s[i] == b'u' || s[i] == b'n' {
            let mut j = i + 1;
            while j < n && s[j] == s[i] {
                j += 1;
            }
            ans = ans * ff[j - i] % MD;
            i = j;
        } else {
            i += 1;
        }
    }
    println!("{}", ans);
}

