use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut lines = input.lines();

    let t: i32 = lines.next().unwrap().parse().unwrap();
    for _ in 0..t {
        let mut first_line = lines.next().unwrap().split_whitespace();
        let n: usize = first_line.next().unwrap().parse().unwrap();
        let u: i32 = first_line.next().unwrap().parse().unwrap();
        let v: i32 = first_line.next().unwrap().parse().unwrap();

        let array: Vec<i32> = lines.next().unwrap().split_whitespace()
            .take(n)
            .map(|s| s.parse().unwrap())
            .collect();

        let mut flag = -1;
        for window in array.windows(2) {
            let diff = window[1] - window[0];
            if diff.abs() > 1 {
                flag = 1;
                break;
            } else if diff.abs() == 1 {
                flag = 0;
            }
        }

        let min = u.min(v);

        let result = match flag {
            -1 => v + min,
            1 => 0,
            _ => min,
        };

        println!("{}", result);
    }
}

