#define LIM 2000
#define NO {puts("NO"); return 0;}

int weight[LIM + 1][LIM + 1], n;

int main(void) {
    int i, j, min;
    scanf("%d", &n);
    for(i = 0; i < n; i++)
        for(j = 0; j < n; j++)
            scanf("%d", &weight[i][j]);

    for(i = 0; i < n; i++) {
        if(weight[i][i] != 0)
            NO;
        for(j = 0; j < i; j++)
            if(weight[i][j] != weight[j][i] || weight[i][j] == 0)
                NO;
    }
    for(i = 0; i < n; i++) {
        min = 0;
        for(j = 0; j < n; j++) {
            if(i != j && weight[i][j] < weight[i][min])
                min = j;
        }
        for(j = 0; j < n; j++) {
            if(abs(weight[i][j] - weight[min][j]) != weight[i][min])
                NO;
        }
    }
    puts("YES");
    return 0;
}

