const int mod = 998244353;
int dp[7][200007], ans[200007];

int main(){
	int n, k;
	scanf("%d %d", &n, &k);
	for (int i = k; i <= n; i += k){
		dp[0][i] = 1;
	}
	for (int i = 1; ; i++){
		int cur = i & 1, pre = cur ^ 1;
		bool flag = false;
		for (int j = 1; j <= n; j++){
			dp[cur][j] = 0;
			ans[j] = (ans[j] + dp[pre][j]) % mod;
		}
		for (int j = k + i; j <= n; j++){
			dp[cur][j] = (dp[pre][j - (k + i)] + dp[cur][j - (k + i)]) % mod;
			flag |= dp[cur][j] > 0;
		}
		if (!flag) break;
	}
	for (int i = 1; i <= n; i++){
		printf("%d ", ans[i]);
	}
	return 0;
}

