use std::io::{self, Write};

fn main() -> io::Result<()> {
    let mut input = String::new();
    io::stdin().read_line(&mut input)?;
    let mut t: i32 = input.trim().parse().unwrap();

    let mut output = Vec::new();

    while t > 0 {
        input.clear();
        io::stdin().read_line(&mut input)?;
        let mut parts = input.trim().split_whitespace();
        let a: i32 = parts.next().unwrap().parse().unwrap();
        let b: i32 = parts.next().unwrap().parse().unwrap();

        if a >= b {
            output.extend(std::iter::repeat("01").take(b as usize));
            output.extend(std::iter::repeat("0").take((a - b) as usize));
        } else {
            output.extend(std::iter::repeat("10").take(a as usize));
            output.extend(std::iter::repeat("1").take((b - a) as usize));
        }

        output.push("\n");
        t -= 1;
    }

    io::stdout().write_all(output.join("").as_bytes())?;
    Ok(())
}

