use std::io::{self, Write};

fn main() -> io::Result<()> {
    let mut input = String::new();
    io::stdin().read_line(&mut input)?;
    let s = input.trim();
    let mut input = String::new();
    io::stdin().read_line(&mut input)?;
    let k: usize = input.trim().parse().unwrap();

    let n = s.len();
    if n % k != 0 {
        writeln!(io::stdout(), "NO")?;
        return Ok(());
    }

    let m = n / k;
    let mut flag = false;

    for i in (0..n).step_by(m) {
        let segment = &s[i..i + m];
        if !is_palindrome(segment) {
            flag = true;
            break;
        }
    }

    if flag {
        writeln!(io::stdout(), "NO")?;
    } else {
        writeln!(io::stdout(), "YES")?;
    }

    Ok(())
}

fn is_palindrome(s: &str) -> bool {
    s.chars().eq(s.chars().rev())
}

