                    if n % 2 == 0 {
                        n /= 2;
                        operation += 1;
                    } else if n % 3 == 0 {
                        n = 2 * n / 3;
                        operation += 1;
                    } else if n % 5 == 0 {
                        n = 4 * n / 5;
                        operation += 1;
                    } else {
                        println!("-1");
                        break;
                    }
                }

                if n == 1 {
                    println!("{}", operation);
                }
            }
        }
    }
}

