            for j in 0..sb {
                let mut x = 0;
                for k in j..sb {
                    if i + x < sa && a.as_bytes()[i + x] == b.as_bytes()[k] {
                        x += 1;
                    } else {
                        break;
                    }
                }
                if x > max {
                    max = x;
                }
            }
        }

        writeln!(stdout, "{}", sa + sb - 2 * max).unwrap();
        t -= 1;
    }
}

