            .trim()
            .split_whitespace()
            .map(|s| s.parse().expect("Please type a number!"))
            .collect();

        let (a, b, c, d) = (numbers[0], numbers[1], numbers[2], numbers[3]);

        let result = if b >= a {
            b
        } else if c <= d {
            u64::MAX // Using u64::MAX to represent -1 as Rust does not have unsigned negative numbers
        } else {
            let diff_ab = a - b;
            let diff_cd = c - d;
            let quotient = diff_ab / diff_cd;
            let remainder = diff_ab % diff_cd;
            b + (quotient + if remainder > 0 { 1 } else { 0 }) * c
        };

        if result == u64::MAX {
            println!("-1");
        } else {
            println!("{}", result);
        }
    }
}

