    let mut r: usize = parts[1] as usize;

    if m > r {
        std::mem::swap(&mut m, &mut r);
    }

    if m != r {
        let l = min((m - 1 + n) % n, (r - 2 + n) % n);
        let r1 = max((m - 1 + n) % n, (r - 2 + n) % n);
        let mut ans: i64 = a[l..=r1].iter().sum();

        let l = (m - 2 + n) % n;
        let r1 = (r - 1 + n) % n;
        let mut temp: i64 = 0;
        let mut d2 = l;
        loop {
            temp += a[d2];
            if d2 == r1 {
                break;
            }
            d2 = (d2 - 1 + n) % n;
        }

        if temp < ans {
            ans = temp;
        }
        println!("{}", ans);
    } else {
        println!("0");
    }
}

