    let mut p = vec![vec!['.'; m]; n];

    for (i, row) in p.iter_mut().enumerate() {
        if (i + 1) % 2 == 1 {
            for cell in row.iter_mut() {
                *cell = '#';
            }
        } else if (i + 1) % 2 == 0 {
            row[m - 1] = '#';
        }

        if (i + 1) % 4 == 0 {
            row[0] = '#';
        }
    }

    let stdout = io::stdout();
    let mut handle = stdout.lock();
    for row in p {
        handle.write_all(row.iter().collect::<String>().as_bytes())?;
        handle.write_all(b"\n")?;
    }

    Ok(())
}

