fn find_combination(mut n: i32) -> (i32, i32) {
    let mut x = 0;
    let mut y = 0;

    while n > 0 {
        if n % 7 == 0 {
            x = n / 7;
            break;
        } else {
            n -= 4;
            y += 1;
        }
    }

    (x, y)
}

