        let length = line.len();
        strings.push(line);
        if length > max_length {
            max_length = length;
        }
    }

    println!("{}", "*".repeat(max_length + 2));

    for (index, s) in strings.iter().enumerate() {
        let diff = max_length - s.len();
        let (left_padding, right_padding) = if diff % 2 == 0 {
            (diff / 2, diff / 2)
        } else {
            if index % 2 == 0 {
                (diff / 2, diff / 2 + 1)
            } else {
                (diff / 2 + 1, diff / 2)
            }
        };

        println!("*{}{}{}", " ".repeat(left_padding), s, " ".repeat(right_padding));
    }

    println!("{}", "*".repeat(max_length + 2));
}

