fn main() {
    let stdin = io::stdin();
    let mut lines = stdin.lock().lines();

    if let Some(Ok(n_str)) = lines.next() {
        let mut n: i32 = n_str.parse().unwrap();

        while n > 0 {
            if let Some(Ok(line)) = lines.next() {
                let parts: Vec<i32> = line.split_whitespace()
                    .map(|s| s.parse().unwrap())
                    .collect();
                let a = parts[0];
                let b = parts[1];
                let c = parts[2];
                let d = parts[3];
                let k = parts[4];

                let x = if a % c == 0 { a / c } else { a / c + 1 };
                let y = if b % d == 0 { b / d } else { b / d + 1 };

                if x + y <= k {
                    println!("{} {}", x, y);
                } else {
                    println!("-1");
                }
            }
            n -= 1;
        }
    }
}

