    let p1 = first_line[1];
    let p2 = first_line[2];
    let p3 = first_line[3];
    let t1 = first_line[4];
    let t2 = first_line[5];

    let mut table = vec![vec![0; 2]; n];
    for row in table.iter_mut() {
        *row = lines.next().unwrap().split_whitespace()
            .map(|s| s.parse().unwrap()).collect();
    }

    let mut sum = 0;
    for row in &table {
        sum += p1 * (row[1] - row[0]);
    }

    for i in 0..n - 1 {
        let gap = table[i + 1][0] - table[i][1];
        sum += match gap {
            x if x <= t1 => p1 * x,
            x if x <= t1 + t2 => p1 * t1 + p2 * (x - t1),
            _ => p1 * t1 + p2 * t2 + p3 * (gap - t1 - t2),
        };
    }

    println!("{}", sum);
}

