    let (first_char, second_char) = if n >= m { ('B', 'G') } else { ('G', 'B') };
    let (primary_count, secondary_count) = if n >= m { (m, n - m) } else { (n, m - n) };

    for _ in 0..primary_count {
        write!(output_file, "{}{}", first_char, second_char)?;
    }
    for _ in 0..secondary_count {
        write!(output_file, "{}", first_char)?;
    }

    Ok(())
}

