use std::io::{self, Read};

fn main() -> io::Result<()> {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input)?;

    let mut parts = input.split_whitespace();
    let n: usize = parts.next().unwrap().parse().unwrap();
    let p: usize = parts.next().unwrap().parse().unwrap();

    let mut str_vec: Vec<char> = parts.next().unwrap().chars().take(n).collect();
    let mut count = 0;

    for i in 0..n-p {
        match (str_vec[i], str_vec[i+p]) {
            ('.', c) if c != '.' => {
                let m = c.to_digit(10).unwrap() as u8;
                str_vec[i] = (1 - m + b'0') as char;
            },
            ('.', '.') => {
                str_vec[i] = '0';
                str_vec[i+p] = '1';
            },
            (c, '.') if c != '.' => {
                let m = c.to_digit(10).unwrap() as u8;
                str_vec[i+p] = (1 - m + b'0') as char;
            },
            (c1, c2) if c1 == c2 && c1 != '.' => {
                count += 1;
            },
            _ => {}
        }
    }

    for i in n-p..n {
        if str_vec[i] == '.' {
            str_vec[i] = '0';
        }
    }

    if count != n-p {
        for c in str_vec {
            print!("{}", c);
        }
    } else {
        println!("No");
    }

    Ok(())
}

