use std::io::{self, Write};

fn main() -> io::Result<()> {
    let stdin = io::stdin();
    let mut stdout = io::stdout();
    let mut buffer = String::new();

    loop {
        buffer.clear();
        if stdin.read_line(&mut buffer)? == 0 {
            break;
        }

        let mut parts = buffer.split_whitespace();
        let n: i32 = parts.next().unwrap().parse().unwrap();
        let m: i32 = parts.next().unwrap().parse().unwrap();

        if m < n - 1 || m > (n * 2 + 2) {
            writeln!(stdout, "-1")?;
            continue;
        }

        if m < n {
            if n == 1 {
                writeln!(stdout, "0")?;
                continue;
            }
            for _ in 0..m {
                write!(stdout, "01")?;
            }
            writeln!(stdout, "0")?;
            continue;
        }

        if n == m {
            for _ in 0..n {
                write!(stdout, "01")?;
            }
            writeln!(stdout)?;
            continue;
        }

        let x = 2 * n - m;
        let mut y = m - n;
        if x < 0 {
            y += x;
        }

        for _ in 0..x {
            write!(stdout, "10")?;
        }
        for _ in 0..y {
            write!(stdout, "110")?;
        }
        if x == -1 {
            write!(stdout, "1")?;
        }
        if x == -2 {
            write!(stdout, "11")?;
        }
        writeln!(stdout)?;
    }

    Ok(())
}

