    let mut iter = input.split_whitespace().map(|s| s.parse::<i32>().unwrap());
    let n = iter.next().unwrap();
    let mut d = iter.next().unwrap();
    let l = iter.next().unwrap();

    let mut x = 1;
    let mut y = l;
    let mut a = vec![0; n as usize];

