            if l - 1 <= d {
                a[i as usize] = l;
                d -= l - 1;
            } else {
                a[i as usize] += d;
                d = 0;
            }
        } else {
            if l - 1 <= d {
                a[i as usize] = 1;
                d -= l - 1;
            } else {
                a[i as usize] -= d;
