#define MAXN 300


int prf[MAXN];

int fri[MAXN][MAXN];

int rank[MAXN];
int order[MAXN];

int N;

int main()
{
	while ( scanf("%d", &N) == 1)
	{
		int i, j, k;
		for ( i = 0; i < N; i++)
		{
			for ( j = 0; j < N; j ++)
			{
				scanf("%d", fri[i] + j);
				--fri[i][j];
			}
		}

		for ( i = 0; i < N; i++)
		{
			scanf("%d", prf + i);
			--prf[i];
			rank[prf[i]] = i;
		}

		for ( i = 0; i < N; i++)
		{
			char find = 0;
			for ( j = 0; j < N && !find; j++)
			{
				int cur = -1;
				for ( k = 0; k < N && !find; k++)
				{
					if ( k != i)
					{
						if ( cur == -1 || rank[k] < rank[cur])
						{
							cur = k;
						}
						if ( cur == fri[i][j])
						{
							find = 1;
							order[i] = k;
						}
					}
				}
			}
		}


		for ( i = 0; i < N; i++)
		{
			printf("%d%c", order[i] + 1, i == N - 1 ? '\n' : ' ');
		}

	}

	return 0;
}

