        let s: String = lines.next().unwrap().unwrap();
        let mut k = true;
        let chars: Vec<char> = s.chars().collect();
        let len = chars.len();

        let mut i = 0;
        while i < len {
            match (chars.get(i), chars.get(i + 1), chars.get(i + 2), chars.get(i + 3)) {
                (Some(&'a'), Some(&'a'), Some(&'a'), Some(&c)) if c != 'a' => {
                    i += 3;
                }
                (Some(&'a'), Some(&'a'), _, _) => {
                    i += 2;
                }
                (Some(&'b'), Some(&'b'), Some(&'b'), Some(&c)) if c != 'b' => {
                    i += 3;
                }
                (Some(&'b'), Some(&'b'), _, _) => {
                    i += 2;
                }
                _ => {
                    k = false;
                    break;
                }
            }
        }

        if k {
            println!("yes");
        } else {
            println!("no");
        }
    }
}

