            for k in (0..j).rev() {
                tmp -= b[i][k];
                tmp += b[i][a[i] - j + k];
                if tmp > max[i][j] {
                    max[i][j] = tmp;
                }
            }
        }
    }

    dp[0] = 1;

    for i in 0..n {
        for j in (0..=m).rev() {
            for k in 1..=a[i].min(m - j) {
                if dp[j] == 0 {
                    continue;
                }
                if dp[j] + max[i][k] > dp[j + k] {
                    dp[j + k] = dp[j] + max[i][k];
                }
            }
        }
    }

    println!("{}", dp[m] - 1);
}

