    let q = first_line[1];

    let mut position = vec![0; n + q];
    let mut actions: Vec<usize> = Vec::with_capacity(q);
    let mut location: Vec<usize> = Vec::with_capacity(n);
    let mut ans: Vec<usize> = vec![0; q];

    let positions_line: Vec<usize> = lines.next().unwrap().split_whitespace()
        .map(|s| s.parse().unwrap()).collect();
    for (i, &pos) in positions_line.iter().enumerate() {
        position[q + i] = pos;
        location.push(q + i);
    }

