        match (m % 2, m % 3, k % 3) {
            (0, _, 0) => println!("{} {}", m, k),
            (0, _, 1) => println!("{} {}", m - 2, k + 2),
            (0, _, _) => println!("{} {}", m - 1, k + 1),
            (_, 0, _) => println!("{} {}", m, k),
            (_, 2, _) => println!("{} {}", m - 2, k + 2),
            _ => println!("{} {}", m - 1, k + 1),
        }
    }
}

