        return Ok(());
    }

    for i in 0..(inw.len() - a) / 2 {
        if inw.chars().nth(keps[i]) != inw.chars().nth(keps[(inw.len() - a) / 2 + i])
            || keps[(inw.len() - a) / 2 + i] < la
        {
            print!(":(");
            return Ok(());
        }
    }

    for i in 0..keps[(inw.len() - a) / 2] {
        print!("{}", inw.chars().nth(i).unwrap());
    }

    io::stdout().flush()?;
    Ok(())
