fn main() -> io::Result<()> {
    let mut input = String::new();
    io::stdin().read_line(&mut input)?;
    let n: usize = input.trim().parse().unwrap();

    let mut prejsni = String::new();
    io::stdin().read_line(&mut prejsni)?;
    let mut prejsni = prejsni.trim().chars().collect::<Vec<_>>();

    for _ in 0..n - 1 {
        let mut zadnji = String::new();
        io::stdin().read_line(&mut zadnji)?;
        let mut zadnji = zadnji.trim().chars().collect::<Vec<_>>();

        for (p, z) in prejsni.iter_mut().zip(zadnji.iter_mut()) {
            match (*p, *z) {
                ('.', _) => *z = '.',
                (_, '.') => {}
                ('?', _) => {}
                (_, '?') => *z = *p,
                (a, b) if a != b => *z = '.',
                _ => {}
            }
        }
        prejsni = zadnji;
    }

    for c in prejsni {
        match c {
            '?' => print!("a"),
            '.' => print!("?"),
            _ => print!("{}", c),
        }
    }
    io::stdout().flush()?;
    Ok(())
}

