int main() {
	int t;

	scanf("%d", &t);
	while (t--) {
		static long long aa[N + 1];
		static int qu[N + 1];
		int n, s, i, l, r, cnt;

		scanf("%d%d", &n, &s);
		for (i = 1; i <= n; i++) {
			scanf("%lld", &aa[i]);
			aa[i] += aa[i - 1];
		}
		cnt = 0;
		l = r = n, qu[cnt++] = n;
		for (i = n - 1; i >= 0; i--) {
			int lower, upper;

			lower = -1, upper = cnt;
			while (upper - lower > 1) {
				int h = (lower + upper) / 2;

				if (s + aa[qu[h]] - aa[i] >= 0)
					upper = h;
				else
					lower = h;
			}
			if (r - l < (lower < 0 ? n : qu[lower] - 1) - i)
				l = i, r = lower < 0 ? n : qu[lower] - 1;
			while (cnt && aa[qu[cnt - 1]] >= aa[i])
				cnt--;
			qu[cnt++] = i;
		}
		if (l == r)
			printf("-1\n");
		else
			printf("%d %d\n", l + 1, r);
	}
