        match c {
            'x' => xcnt += 1,
            'y' => ycnt += 1,
            _ => {}
        }
    }

    let mut stdout = io::stdout();
    if xcnt > ycnt {
        for _ in 0..(xcnt - ycnt) {
            stdout.write_all(b"x")?;
        }
    } else {
        for _ in 0..(ycnt - xcnt) {
            stdout.write_all(b"y")?;
        }
    }
    stdout.write_all(b"\n")?;

    Ok(())
}

