fn main() {
    let stdin = io::stdin();
    let mut lines = stdin.lock().lines().map(|l| l.unwrap());

    let first_line: Vec<i32> = lines.next().unwrap().split_whitespace()
        .map(|s| s.parse().unwrap()).collect();
    let n = first_line[0] as usize;
    let m = first_line[1] as usize;

    let mut a = 0;
    let mut b = 0;

    for _ in 0..n {
        let x: i32 = lines.next().unwrap().parse().unwrap();
        if x == -1 {
            a += 1;
        } else {
            b += 1;
        }
    }

    for _ in 0..m {
        let lr: Vec<i32> = lines.next().unwrap().split_whitespace()
            .map(|s| s.parse().unwrap()).collect();
        let l = lr[0] as usize;
        let r = lr[1] as usize;
        let len = r - l + 1;

        if len % 2 == 1 {
            println!("0");
        } else {
            if a >= len / 2 && b >= len / 2 {
                println!("1");
            } else {
                println!("0");
            }
        }
    }
}

