use std::io::{self, Write};

fn main() -> io::Result<()> {
    let mut input = String::new();
    io::stdin().read_line(&mut input)?;
    let mut iter = input.split_whitespace().map(|s| s.parse::<i32>().unwrap());
    let n = iter.next().unwrap();
    let m = iter.next().unwrap();
    let num = iter.next().unwrap();

    let mut j = 1;
    let mut k = 1;
    let mut output = Vec::new();

    for _ in 0..num - 1 {
        output.push(2);
        if k == m && j % 2 != 0 {
            output.extend_from_slice(&[j, k, j + 1, k]);
            k += 1;
        } else if j % 2 != 0 {
            output.extend_from_slice(&[j, k, j, k + 1]);
            k += 2;
        } else {
            output.extend_from_slice(&[j, k, j, k - 1]);
            k -= 2;
        }
        if m + 1 == k {
            j += 1;
            k = m - m % 2;
        }
        if k == 0 {
            j += 1;
            k = 1;
        }
    }

    output.push(m * n - 2 * num + 2);
    for _ in 0..m * n - 2 * num + 2 {
        if j % 2 != 0 {
            output.extend_from_slice(&[j, k]);
            k += 1;
        } else {
            output.extend_from_slice(&[j, k]);
            k -= 1;
        }
        if k > m {
            k = m;
            j += 1;
        }
        if k == 0 {
            k = 1;
            j += 1;
        }
    }

    let stdout = io::stdout();
    let mut handle = stdout.lock();
    for (i, &val) in output.iter().enumerate() {
        if i > 0 {
            write!(handle, " ")?;
        }
        write!(handle, "{}", val)?;
    }
    writeln!(handle)?;

    Ok(())
}

