use std::io::{self, Write};

fn main() -> io::Result<()> {
    let mut input = String::new();
    io::stdin().read_line(&mut input)?;
    let n: usize = input.trim().parse().unwrap();

    input.clear();
    io::stdin().read_line(&mut input)?;
    let str = input.trim();

    let mut output = Vec::new();

    if n % 2 == 0 {
        for chunk in str.as_bytes().chunks(2) {
            output.extend_from_slice(chunk);
            if chunk.len() == 2 {
                output.push(b'-');
            }
        }
    } else if n % 3 == 0 {
        for chunk in str.as_bytes().chunks(3) {
            output.extend_from_slice(chunk);
            if chunk.len() == 3 {
                output.push(b'-');
            }
        }
    } else {
        let mid = n / 2;
        for chunk in str.as_bytes()[..mid].chunks(2) {
            output.extend_from_slice(chunk);
            if chunk.len() == 2 {
                output.push(b'-');
            }
        }
        output.extend_from_slice(&str.as_bytes()[mid..mid + 3]);
        if mid + 3 < n {
            output.push(b'-');
        }
        for chunk in str.as_bytes()[mid + 3..].chunks(2) {
            output.extend_from_slice(chunk);
            if chunk.len() == 2 {
                output.push(b'-');
            }
        }
    }

    if !output.is_empty() && *output.last().unwrap() == b'-' {
        output.pop();
    }

    io::stdout().write_all(&output)?;
    Ok(())
}

