                    write!(stdout, "L").unwrap();
                } else {
                    write!(stdout, "S").unwrap();
                }
            }
            writeln!(stdout).unwrap();
        }
    } else if k > (n * n + 1) as i32 / 2 {
        writeln!(stdout, "NO").unwrap();
    } else {
        writeln!(stdout, "YES").unwrap();
        for i in 0..n {
            for j in 0..n {
                if (i + j) % 2 == 0 && k > 0 {
                    write!(stdout, "L").unwrap();
                    k -= 1;
                } else {
                    write!(stdout, "S").unwrap();
                }
            }
            writeln!(stdout).unwrap();
        }
    }
}

