fn main() {
    let stdin = io::stdin();
    let mut lines = stdin.lock().lines();

    if let Some(Ok(n_str)) = lines.next() {
        let n: usize = n_str.parse().unwrap();
        for _ in 0..n {
            if let Some(Ok(m_str)) = lines.next() {
                let m: usize = m_str.parse().unwrap();
                let mut x: Vec<i32> = vec![0; m + 1];
                if let Some(Ok(line)) = lines.next() {
                    let values: Vec<i32> = line.split_whitespace()
                        .map(|s| s.parse().unwrap())
                        .collect();
                    for (i, &value) in values.iter().enumerate() {
                        x[i + 1] = value;
                    }
                }

                loop {
                    let mut swapped = false;
                    for j in 1..m {
                        for g in j + 1..=m {
                            if (j as i32 - x[j]) == (g as i32 - x[g]) {
                                x.swap(j, g);
                                swapped = true;
                            }
                        }
                    }
                    if !swapped {
                        break;
                    }
                }

                for j in 1..=m {
                    print!("{} ", x[j]);
                }
                println!();
            }
        }
    }
}

