use std::io::{self, BufRead};

fn nme(n: i32, a: i32, c: i32) -> i32 {
    if (c - a) < 0 {
        2 * (n - a) + (a - c)
    } else {
        c - a
    }
}

fn main() {
    let stdin = io::stdin();
    let mut lines = stdin.lock().lines();

    let k: i32 = lines.next().unwrap().unwrap().parse().unwrap();

    for _ in 0..k {
        let line = lines.next().unwrap().unwrap();
        let parts: Vec<i32> = line.split_whitespace()
                                 .map(|s| s.parse().unwrap())
                                 .collect();
        let (n, m, a, b, c, d) = (parts[0], parts[1], parts[2], parts[3], parts[4], parts[5]);

        if nme(n, a, c) <= nme(m, b, d) {
            let distance = if a <= c { c - a } else { n - a + n - c };
            println!("{}", distance);
        } else {
            let distance = if b <= d { d - b } else { m - b + m - d };
            println!("{}", distance);
        }
    }
}

