            if c2.is_ascii_uppercase() {
                let index = (c2 as u8 - b'A') as usize;
                if key[index] == 0 {
                    count += 1;
                } else {
                    key[index] -= 1;
                }
            }
        }
    }

    println!("{}", count);
    Ok(())
