        let parts: Vec<i32> = line.split_whitespace()
                                 .map(|s| s.parse().unwrap())
                                 .collect();
        let (n, m, a, b, c, d) = (parts[0], parts[1], parts[2], parts[3], parts[4], parts[5]);

        if nme(n, a, c) <= nme(m, b, d) {
            let distance = if a <= c { c - a } else { n - a + n - c };
            println!("{}", distance);
        } else {
            let distance = if b <= d { d - b } else { m - b + m - d };
            println!("{}", distance);
        }
    }
}

