#define ll unsigned long long int

int main()
{
	ll N, M, K, L, ans;
	scanf("%llu %llu %llu %llu", &N, &M, &K, &L);
	ans = L + K;
	if(ans % M == 0)
	{
		ans = ans / M;
	}
	else
	{
		ans = ans / M + 1;
	}
	if(ans * M <= N)
	{
		printf("%llu\n", ans);
	}
	else
	{
		printf("-1\n");
	}
	return 0;
}

