    let mut lines = input.lines();
    let mut t: i64 = lines.next().unwrap().parse().unwrap();

    while t > 0 {
        let n: usize = lines.next().unwrap().parse().unwrap();
        let mut arr: Vec<i64> = vec![0; n + 1];
        for (i, line) in lines.by_ref().take(n).enumerate() {
            arr[i + 1] = line.parse().unwrap();
        }

        let mut ct = 0;
        for i in 1..=n {
            let index = arr[i] - i as i64;
            let mut j = index;
            while j <= n as i64 {
                if j > 0 {
                    if arr[i] * arr[j as usize] == i as i64 + j && i < j as usize {
                        ct += 1;
                    }
                }
                j += arr[i];
            }
        }

        println!("{}", ct);
        t -= 1;
    }
}

