#define ll long long int

int main(void)
{
	int t;
	scanf("%d",&t);
	while(t--)
	{
		ll n,k,b,s;
		scanf("%lld%lld%lld%lld",&n,&k,&b,&s);
		ll x = b*k;
		ll y = s - x;
		if( s < k*b || s  > x + (k-1)*n )
		{
			printf("-1\n");
			continue;
		}
		if( n == 1)
		{
			printf("%d\n",s);
			continue;
		}
		ll p = y;
		if( (k-1) < y)
		    p = k-1;	
		for(int i = 0; i < (n-1); i++)
		{
			if(p < y)
			{
				printf("%lld ",p);
				y -= p;
			}else{
				printf("%lld ",y);
				y = 0;
				p = 0;
			}
		}

		printf("%lld\n",x+y);
	}
	return 0;
}

