			max_dmg[i][j] = 0;
		}
	}
	for (i = 0; i < n; i++) {
		for (j = 0; j <= widths[i]; j++) {
			for (k = 0; k <= j; k++) {
				max_dmg[i][j] = MAX(max_dmg[i][j], cum_vals[i][k] + cum_vals[i][widths[i]] - cum_vals[i][widths[i]-j+k]);
			}
		}
	}
	for (i = 0; i < n; i++) {
		for (j = 0; j <= m; j++) {
			for (k = 0; k <= widths[i] && k+j <= m; k++) {
				dp[i+1][j+k] = MAX(dp[i+1][j+k], dp[i][j] + max_dmg[i][k]);
			}
		}
	}
