fn main() {
    let mut input = String::new();
    std::io::stdin().read_line(&mut input).unwrap();
    let mut parts = input.split_whitespace();
    let n: usize = parts.next().unwrap().parse().unwrap();
    let m: usize = parts.next().unwrap().parse().unwrap();

    let mut widths = vec![0; n];
    let mut cum_vals = vec![vec![0; 105]; n];
    let mut max_dmg = vec![vec![0; 101]; n];
    let mut dp = vec![vec![0; 10001]; n + 1];

    for (i, width) in widths.iter_mut().enumerate() {
        input.clear();
        std::io::stdin().read_line(&mut input).unwrap();
        let mut parts = input.split_whitespace();
        *width = parts.next().unwrap().parse().unwrap();
        cum_vals[i][0] = 0;
        for j in 1..=*width {
            cum_vals[i][j] = parts.next().unwrap().parse().unwrap();
            cum_vals[i][j] += cum_vals[i][j - 1];
            max_dmg[i][j] = 0;
        }
    }

    for i in 0..n {
        for j in 0..=widths[i] {
            for k in 0..=j {
                max_dmg[i][j] = cmp::max(max_dmg[i][j], cum_vals[i][k] + cum_vals[i][widths[i]] - cum_vals[i][widths[i] - j + k]);
            }
        }
    }

    for i in 0..n {
        for j in 0..=m {
            for k in 0..=widths[i] {
                if j + k <= m {
                    dp[i + 1][j + k] = cmp::max(dp[i + 1][j + k], dp[i][j] + max_dmg[i][k]);
                }
            }
        }
    }

    println!("{}", dp[n][m]);
}

