use std::io::{self, BufRead};

fn main() {
    let stdin = io::stdin();
    let mut lines = stdin.lock().lines();

    let t: usize = lines.next().unwrap().unwrap().parse().unwrap();
    for _ in 0..t {
        let n: usize = lines.next().unwrap().unwrap().parse().unwrap();
        let arr: Vec<i32> = lines.next().unwrap().unwrap()
            .split_whitespace()
            .map(|s| s.parse().unwrap())
            .collect();

        let sum: i64 = arr.iter().map(|&x| x as i64).sum();
        match n {
            1 => println!("0"),
            _ if sum % n as i64 != 0 => println!("-1"),
            _ => {
                let target = sum / n as i64;
                let count: i64 = arr.iter().filter(|&&x| x as i64 > target).count() as i64;
                println!("{}", count);
            }
        }
    }
}

