#include <stdio.h>
#include <ctype.h>
#include <string.h>

char bar[1000005];

int main(void) {
    int len;
    int i;
    int pivot = 0;
    long long int balance;

    scanf(" %s", bar);
    len = strlen(bar);

    for (i = 0; i < len; i++) {
        if (bar[i] == '^') {
            pivot = i;
            break;
        }
    }
    balance = 0;
    for (i = 0; i < len; i++) {
        if (isdigit(bar[i])) {
            balance += (bar[i] - '0') * (i - pivot);
        }
    }

    if (balance < 0) {
        printf("left\n");
    } else if (balance == 0) {
        printf("balance\n");
    } else {
        printf("right\n");
    }
    return 0;
}

