use std::io::{self, Write};

fn main() -> io::Result<()> {
    let mut input = String::new();
    io::stdin().read_line(&mut input)?;
    let bar = input.trim_end();

    let pivot = bar.find('^').unwrap_or(bar.len());
    let balance: i64 = bar.chars()
        .enumerate()
        .filter_map(|(i, c)| c.to_digit(10).map(|d| (d as i64) * (i as i64 - pivot as i64)))
        .sum();

    let result = match balance {
        _ if balance < 0 => "left",
        0 => "balance",
        _ => "right",
    };

    writeln!(io::stdout(), "{}", result)?;
    Ok(())
}

