fn main() {
    let mut input = String::new();
    io::stdin().read_line(&mut input).unwrap();
    let n: usize = input.trim().parse().unwrap();

    let mut a = vec![0; n];
    for i in 0..n {
        input.clear();
        io::stdin().read_line(&mut input).unwrap();
        a[i] = input.trim().parse().unwrap();
    }

    let mut j = 0;
    let mut start = 0;
    for (i, &value) in a.iter().enumerate() {
        if value == 0 {
            for k in 0..j {
                a[k] = j - k;
            }
            start = i;
            break;
        }
        j = i + 1;
    }

    j = n;
    let mut last = 0;
    for (i, &value) in a.iter().enumerate().rev() {
        if value == 0 {
            for k in 1..(n - j + 1) {
                a[j + k - 1] = k;
            }
            last = i;
            break;
        }
        j = i;
    }

    let mut m = 1;
    for i in (start + 1)..=last {
        if a[i] == 0 {
            for (p, h) in (start + 1..=start + (i - start) / 2).zip((i - 1..start).rev()) {
                a[p] = m;
                a[h] = m;
                m += 1;
            }
            m = 1;
            start = i;
        }
    }

    let mut output = String::new();
    for (i, &value) in a.iter().enumerate() {
        if i != n - 1 {
            output.push_str(&format!("{} ", value));
        } else {
            output.push_str(&format!("{}\n", value));
        }
    }
    io::stdout().write_all(output.as_bytes()).unwrap();
}

