use std::io::{self, Read};

const N: usize = 100000;
const K: usize = 100;
const MD: i64 = 998244353;

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let n: usize = iter.next().unwrap().parse().unwrap();
    let k: usize = iter.next().unwrap().parse().unwrap();
    let len: usize = iter.next().unwrap().parse().unwrap();

    if len == 1 {
        println!("0");
        return;
    }

    let mut ii = vec![-1; K + 1];
    let mut dp = vec![vec![0; K + 1]; N + 1];
    let mut dq = vec![vec![0; K + 1]; N + 1];

    for j in 1..=k {
        dq[0][j] = 1;
    }

    for i in 1..=n {
        let a: i32 = iter.next().unwrap().parse().unwrap();
        let mut sum = 0;

        for j in 1..=k {
            let mut h = i - len + 1;
            if h < ii[j] as usize {
                h = ii[j] as usize;
            }
            dp[i][j] = (dq[i - 1][j] - if h <= 0 { 0 } else { dq[h - 1][j] } + MD) % MD;
            if a != -1 && j != a as usize {
                dp[i][j] = 0;
            }
            sum = (sum + dp[i][j]) % MD;
        }

        for j in 1..=k {
            dq[i][j] = (dq[i - 1][j] + sum - dp[i][j] + MD) % MD;
        }

        if a != -1 {
            for j in 1..=k {
                if j != a as usize {
                    ii[j] = i as i32;
                }
            }
        }
    }

    let mut ans = 0;
    for j in 1..=k {
        ans = (ans + dp[n][j]) % MD;
    }

    println!("{}", ans);
}

