    let t: usize = lines.next().unwrap().unwrap().parse().unwrap();
    for _ in 0..t {
        let line = lines.next().unwrap().unwrap();
        let mut parts = line.split_whitespace();
        let p: i64 = parts.next().unwrap().parse().unwrap();
        let a: i64 = parts.next().unwrap().parse().unwrap();
        let b: i64 = parts.next().unwrap().parse().unwrap();
        let c: i64 = parts.next().unwrap().parse().unwrap();

        if p % a == 0 || p % b == 0 || p % c == 0 {
            println!("0");
            continue;
        }

        let a = a - p % a;
        let b = b - p % b;
        let c = c - p % c;

        let result = match (a, b, c) {
            (a, b, c) if a >= b && b >= c => c,
            (a, b, c) if a >= c && c >= b => b,
            (a, b, c) if b >= c && c >= a => a,
            (a, b, c) if b >= a && a >= c => c,
            (a, b, c) if c >= a && a >= b => b,
            (a, b, c) if c >= b && b >= a => a,
            _ => unreachable!(),
        };

        println!("{}", result);
