            for _ in 0..j {
                write!(handle, "5")?;
            }
            for _ in 0..(n - t) {
                write!(handle, "0")?;
            }
        } else {
            writeln!(handle, "-1")?;
        }
    } else {
        if t == n {
            writeln!(handle, "-1")?;
        } else {
            writeln!(handle, "0")?;
        }
    }

