        input.clear();
        io::stdin().read_line(&mut input).unwrap();
        let mut parts = input.trim().split_whitespace();
        let n: usize = parts.next().unwrap().parse().unwrap();
        let a: i32 = parts.next().unwrap().parse().unwrap();
        let b: i32 = parts.next().unwrap().parse().unwrap();

        let mut c = vec![0; n + 1];
        c[1] = a;
        c[n] = b;

        let mut ans = 2;
        for i in (1..=n).rev() {
            if i == a as usize || i == b as usize {
                continue;
            }
            c[ans] = i as i32;
            ans += 1;
        }

        let mut min = 999999;
        for i in 1..=n / 2 {
            if c[i] < min {
                min = c[i];
            }
        }

        let mut max = 0;
        for i in n / 2 + 1..=n {
            if c[i] > max {
                max = c[i];
            }
        }

        if min != a || max != b {
            println!("-1");
            t -= 1;
            continue;
        }

