use std::io::{self, BufRead, BufReader, Write};

fn main() -> io::Result<()> {
    let input = File::open("input.txt")?;
    let output = File::create("output.txt")?;
    let reader = BufReader::new(input);
    let mut lines = reader.lines();

    let n: usize = lines.next().unwrap()?.parse().unwrap();
    let mut arr = vec![0; n + 1];
    for (i, line) in lines.take(n).enumerate() {
        arr[i + 1] = line?.parse().unwrap();
    }

    let mut freq_neg = vec![0; n + 1];
    let mut freq_zero = vec![0; n + 1];

    for i in 1..=n {
        if arr[i] == 0 {
            freq_zero[i] += 1;
        } else if arr[i] < 0 {
            freq_neg[i] += 1;
        }
        freq_neg[i] += freq_neg[i - 1];
        freq_zero[i] += freq_zero[i - 1];
    }

    let mut res = i32::MAX - 2;
    for i in 1..n {
        let changes = i as i32 - freq_neg[i] + freq_neg[n] - freq_neg[i] + freq_zero[n] - freq_zero[i];
        res = cmp::min(res, changes);
    }

    let mut writer = io::BufWriter::new(output);
    writeln!(writer, "{}", res)?;
    Ok(())
}

