            c1 += 1;
        } else {
            break;
        }
    }

    let mut c2 = 0;
    for &ch in a.iter().rev() {
        if ch == a[n - 1] {
            c2 += 1;
        } else {
            break;
        }
    }

    let result = if a[0] != a[n - 1] {
        (c1 + c2 + 1) % MOD
    } else {
        ((c1 + 1) * (c2 + 1)) % MOD
    };

