use std::io::{self, Write};

fn main() -> io::Result<()> {
    let mut input = String::new();
    io::stdin().read_line(&mut input)?;
    let input = input.trim_end();
    let mut a: Vec<char> = input.chars().collect();
    a.push('\0'); // Simulate C string termination

    let mut c = Vec::with_capacity(a.len());
    c.push(a[0]);
    let mut cnt = 1;
    for &ch in &a[1..] {
        if ch == *c.last().unwrap() && cnt < 2 {
            cnt += 1;
            c.push(ch);
        } else if ch != *c.last().unwrap() {
            c.push(ch);
            cnt = 1;
        }
    }

    let mut b = Vec::with_capacity(c.len());
    b.push(c[0]);
    cnt = 0;
    for window in c.windows(3) {
        if window[1] == window[0] && cnt < 1 {
            cnt += 1;
            b.push(window[1]);
        } else if window[1] != window[0] {
            b.push(window[1]);
            if window[1] != window[2] && cnt == 1 {
                cnt = 0;
            }
        }
    }
    if c.len() > 1 && c[c.len() - 2] != c[c.len() - 1] {
        b.push(c[c.len() - 1]);
    }

    let result: String = b.into_iter().take_while(|&ch| ch != '\0').collect();
    writeln!(io::stdout(), "{}", result)?;
    Ok(())
}

