#define MOD 1000000007

int main(void)
{
    static int dp[101][2550];
    int i, j, k;
    int len, res;
    int t;
    char str[128];

    for (i = 0; i < 26; i++){
        dp[1][i] = 1;
    }

    for (i = 1; i <= 100; i++){
        for (j = 0; j <= 2500; j++){
            for (k = 0; k < 26; k++){
                if (j - k >= 0){
                    dp[i][j] += dp[i - 1][j - k];
                    if (dp[i][j] >= MOD){
                        dp[i][j] -= MOD;
                    }
                }
            }
        }
    }

    scanf("%d", &t);

    for (i = 0; i < t; i++){
        scanf("%s", str);
        len = strlen(str);
        res = 0;
        for (j = 0; j < len; j++){
            res += str[j] - 'a';
        }
        printf("%d\n", (dp[len][res] + MOD - 1) % MOD);
    }

    return (0);
}

