            0
        } else if n % 2 == 1 && one == zero - 1 {
            0
        } else {
            println!("-1");
            continue;
        };

        let mut moves = moves;
        for i in 0..n {
            if i % 2 != num[i] as usize % 2 {
                for j in (i + 1..n).step_by(2) {
                    if i % 2 == num[j] as usize % 2 {
                        num.swap(i, j);
                        moves += 1;
                        break;
                    }
                }
            }
        }

        println!("{}", moves);
