#define N	200000
#define MD	998244353

int main() {
	static int ans[N + 1], dp[N + 1];
	int n, k, i, zero;

	scanf("%d%d", &n, &k);
	dp[0] = 1;
	while (1) {
		for (i = k; i <= n; i++)
			dp[i] = (dp[i] + dp[i - k]) % MD;
		for (i = n; i >= 0; i--)
			dp[i] = i >= k ? dp[i - k] : 0;
		for (i = 0; i <= n; i++)
			ans[i] = (ans[i] + dp[i]) % MD;
		zero = 1;
		for (i = 0; i <= n; i++)
			if (dp[i] > 0) {
				zero = 0;
				break;
			}
		if (zero)
			break;
		k++;
	}
	for (i = 1; i <= n; i++)
		printf("%d ", ans[i]);
	printf("\n");
	return 0;
}

