    }

    let ans = match increase {
        None => 0,
        Some(increase) => {
            if an[0] < an[n - 1] {
                -1
            } else {
                let mut pre = an[increase];
                let mut ans = (n - increase) as i32;
                for &value in &an[increase + 1..] {
                    if value < pre {
                        ans = -1;
                        break;
                    }
                    pre = value;
                }
                ans
            }
        }
    };

    println!("{}", ans);
}

