            pairs.push((open_index, i));
        }
    }

    let m = (n - k) / 2;
    for &(a, b) in &pairs[..m] {
        flag[a] = true;
        flag[b] = true;
    }

    let mut output = String::new();
    for (i, c) in str_input.chars().enumerate() {
        if !flag[i] {
            output.push(c);
        }
    }

    io::stdout().write_all(output.as_bytes())?;
    Ok(())
}

