fn main() -> io::Result<()> {
    let stdin = io::stdin();
    let mut lines = stdin.lock().lines();

    let n: u16 = match lines.next() {
        Some(Ok(line)) => line.parse().map_err(|_| io::Error::new(io::ErrorKind::InvalidInput, "Invalid number"))?,
        _ => return Err(io::Error::new(io::ErrorKind::UnexpectedEof, "No input")),
    };

    if n < 2 || n > 10000 {
        return Err(io::Error::new(io::ErrorKind::InvalidInput, "n out of bounds"));
    }

    let mut sl1 = 0;
    let mut sr1 = 0;

    for _ in 0..n {
        let line = match lines.next() {
            Some(Ok(line)) => line,
            _ => return Err(io::Error::new(io::ErrorKind::UnexpectedEof, "Not enough lines")),
        };

        let parts: Vec<&str> = line.split_whitespace().collect();
        if parts.len() != 2 {
            return Err(io::Error::new(io::ErrorKind::InvalidInput, "Invalid line format"));
        }

        let l: u16 = parts[0].parse().map_err(|_| io::Error::new(io::ErrorKind::InvalidInput, "Invalid number"))?;
        let r: u16 = parts[1].parse().map_err(|_| io::Error::new(io::ErrorKind::InvalidInput, "Invalid number"))?;

        if l > 1 || r > 1 {
            return Err(io::Error::new(io::ErrorKind::InvalidInput, "l or r out of bounds"));
        }

        if l == 1 {
            sl1 += 1;
        }
        if r == 1 {
            sr1 += 1;
        }
    }

    let sl0 = n - sl1;
    let sr0 = n - sr1;
    let tl = sl0.min(sl1);
    let tr = sr0.min(sr1);
    let t = tl + tr;

    println!("{}", t);
    Ok(())
}

