    if n < 1 || n > 100000 {
        return Err(io::Error::new(io::ErrorKind::InvalidInput, "n out of bounds"));
    }

    let mut l = Vec::with_capacity(n);
    let mut r = Vec::with_capacity(n);
    let mut sl = 0;
    let mut sr = 0;

