fn main() -> io::Result<()> {
    let stdin = io::stdin();
    let mut lines = stdin.lock().lines();

    let n: u16 = match lines.next() {
        Some(Ok(line)) => line.parse().map_err(|_| io::Error::new(io::ErrorKind::InvalidInput, "Invalid number"))?,
        _ => return Err(io::Error::new(io::ErrorKind::UnexpectedEof, "No input")),
    };

    if n < 1 || n > 1000 {
        return Err(io::Error::new(io::ErrorKind::InvalidInput, "n out of bounds"));
    }

    let mut fa = 0;
    for _ in 0..n {
        let a: u32 = match lines.next() {
            Some(Ok(line)) => line.parse().map_err(|_| io::Error::new(io::ErrorKind::InvalidInput, "Invalid number"))?,
            _ => return Err(io::Error::new(io::ErrorKind::UnexpectedEof, "Not enough numbers for fa")),
        };

        if a > 1000000000 {
            return Err(io::Error::new(io::ErrorKind::InvalidInput, "a out of bounds"));
        }

        fa |= a;
    }

    let mut fb = 0;
    for _ in 0..n {
        let b: u32 = match lines.next() {
            Some(Ok(line)) => line.parse().map_err(|_| io::Error::new(io::ErrorKind::InvalidInput, "Invalid number"))?,
            _ => return Err(io::Error::new(io::ErrorKind::UnexpectedEof, "Not enough numbers for fb")),
        };

        if b > 1000000000 {
            return Err(io::Error::new(io::ErrorKind::InvalidInput, "b out of bounds"));
        }

        fb |= b;
    }

    println!("{}", fa + fb);
    Ok(())
}

