            xy.push((line[0] - 1, line[1] - 1));
        }

        let mut colored: Vec<Vec<i32>> = vec![vec![0; nm[0] as usize], vec![0; nm[1] as usize]];
        let mut colored_cnt: [i32; 2] = [0, 0];
