    for (i, row_chars) in grid.iter().enumerate() {
        if let Some((j, _)) = row_chars.iter().enumerate().find(|&(_, &c)| c == '.') {
            row[i] = j;
            count += 1;
        }
    }

    if count == n {
        for i in 0..n {
            println!("{} {}", i + 1, row[i] + 1);
        }
        return;
    }

    let mut col: Vec<usize> = vec![0; n];
    count = 0;
    for j in 0..n {
        if let Some((i, _)) = grid.iter().enumerate().find(|&(_, row_chars)| row_chars[j] == '.') {
            col[j] = i;
            count += 1;
        }
    }

    if count == n {
        for i in 0..n {
            println!("{} {}", col[i] + 1, i + 1);
        }
    } else {
        println!("-1");
    }
}

