fn main() -> io::Result<()> {
    let mut input = String::new();
    io::stdin().read_line(&mut input)?;
    let mut iter = input.split_whitespace();
    let n: i32 = iter.next().unwrap().parse().unwrap();
    let m: i32 = iter.next().unwrap().parse().unwrap();

    let mut output = Vec::new();

    if n > m + 1 || n * 2 + 2 < m {
        output.push(b'-');
        output.push(b'1');
        output.push(b'\n');
    } else if n == m + 1 {
        output.push(b'0');
        output.extend(std::iter::repeat(b"10").take(m as usize).flatten());
        output.push(b'\n');
    } else if n == (m + 1) / 2 - 1 {
        if m % 2 == 1 {
            output.push(b'1');
        } else {
            output.extend_from_slice(b"11");
        }
        output.extend(std::iter::repeat(b"011").take(n as usize).flatten());
        output.push(b'\n');
    } else {
        let y = m - n;
        let x = 2 * n - m;
        output.extend(std::iter::repeat(b"110").take(y as usize).flatten());
        output.extend(std::iter::repeat(b"10").take(x as usize).flatten());
        output.push(b'\n');
    }

    io::stdout().write_all(&output)?;
    Ok(())
}

