use std::io::{self, Write};

fn main() -> io::Result<()> {
    let mut input = String::new();
    io::stdin().read_line(&mut input)?;
    let mut iter = input.split_whitespace();
    let n: usize = iter.next().unwrap().parse().unwrap();
    let m: usize = iter.next().unwrap().parse().unwrap();

    let q = 2 * (m - 2 * n) - 1;
    let mut a = vec![0; m];

    if m <= 2 * n {
        for (i, s) in a.iter_mut().enumerate() {
            *s = (i + 1) as i32;
        }
    } else if m == 4 * n {
        let mut s = 2 * n + 1;
        for i in (0..m).step_by(2) {
            a[i] = s as i32;
            s += 1;
        }
        s = 1;
        for i in (1..m).step_by(2) {
            a[i] = s as i32;
            s += 1;
        }
    } else if m > 2 * n && m < 4 * n {
        let mut s = 2 * n + 1;
        for i in (0..q).step_by(2) {
            a[i] = s as i32;
            s += 1;
        }
        s = 1;
        for i in (1..q - 1).step_by(2) {
            a[i] = s as i32;
            s += 1;
        }
        s = (q - 1) / 2 + 1;
        for i in q..m {
            a[i] = s as i32;
            s += 1;
        }
    }

    for num in a {
        print!("{} ", num);
    }
    io::stdout().flush()?;
    Ok(())
}

