            while frequency[index] > 0 && sum > n {
                sum -= index as i32 + 1;
                frequency[index] -= 1;
            }
        }

        for c in s.chars() {
            let index = (c as u8 - b'a') as usize;
            if frequency[index] > 0 {
                print!("{}", c);
                frequency[index] -= 1;
            }
        }
        println!();
    }
}

