    if a[0] > 500000 {
        println!("{}", 1000000 - a[0]);
        return;
    }

    let mut time1 = 0;
    let mut time2 = 0;

    for (&value, &prev) in a.iter().skip(1).zip(&a) {
        if value > 500000 {
            time1 = prev - 1;
            break;
        }
    }

    for (&value, &next) in a.iter().rev().skip(1).zip(&a.iter().rev().skip(1).collect::<Vec<_>>()) {
        if value <= 500000 {
            time2 = 1000000 - next;
            break;
        }
    }

    if time1 > time2 {
        println!("{}", time1);
    } else {
        println!("{}", time2);
    }
}

