int main() {
	static int ii[K + 1], dp[N + 1][K + 1], dq[N + 1][K + 1];
	int n, k, len, h, i, j, ans;

	scanf("%d%d%d", &n, &k, &len);
	if (len == 1) {
		printf("0\n");
		return 0;
	}
	memset(ii, -1, sizeof ii);
	for (j = 1; j <= k; j++)
		dq[0][j] = 1;
	for (i = 1; i <= n; i++) {
		int a, sum;

		scanf("%d", &a);
		sum = 0;
		for (j = 1; j <= k; j++) {
			h = i - len + 1;
			if (h < ii[j])
				h = ii[j];
			dp[i][j] = (dq[i - 1][j] - (h <= 0 ? 0 : dq[h - 1][j]) + MD) % MD;
			if (a != -1 && j != a)
				dp[i][j] = 0;
			sum = (sum + dp[i][j]) % MD;
		}
		for (j = 1; j <= k; j++)
			dq[i][j] = (dq[i - 1][j] + sum - dp[i][j] + MD) % MD;
		if (a != -1)
			for (j = 1; j <= k; j++)
				if (j != a)
					ii[j] = i;
	}
