                    cache[i][j] = partials[j];
                    cache[i][j] %= 1_000_000_007;
                }
            }
            test = true;
        } else {
            if test {
                cache[i][0] = 0;
                for j in 1..=n {
                    cache[i][j] = cache[i - 1][j - 1];
                }
                test = false;
            } else {
                for j in 0..=n {
                    cache[i][j] = partials[j];
                    cache[i][j] %= 1_000_000_007;
                }
            }
        }
        partials[n] = cache[i][n];
        for k in (0..n).rev() {
            partials[k] = partials[k + 1] + cache[i][k];
            partials[k] %= 1_000_000_007;
        }
    }

    let sum: u64 = cache[n].iter().sum::<u64>() % 1_000_000_007;
    println!("{}", sum);
}

