use std::io::{self, Read};

const MAXN: usize = 2033;
const MAXK: usize = 2033;
const MOD: u64 = 1_000_000_007;

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut lines = input.lines();

    while let Some(line) = lines.next() {
        let mut parts = line.split_whitespace();
        let n: usize = parts.next().unwrap().parse().unwrap();
        let k: usize = parts.next().unwrap().parse().unwrap();
        let s: String = parts.next().unwrap().to_string();
        let s: Vec<char> = std::iter::once('0').chain(s.chars()).collect();

        let mut dp = vec![vec![0; MAXK + 1]; MAXN + 1];
        let mut sum = vec![0; MAXK + 1];

        dp[0][0] = 1;
        sum[0] = 1;

        for i in 1..=n {
            let add = n - i + 1;
            for j in 0..=k {
                dp[i][j] = (sum[j] * (s[i] as u64 - 'a' as u64)) % MOD;
                for (p, q) in (0..=i-1).zip((add..).step_by(add)) {
                    if j >= q {
                        dp[i][j] = (dp[i][j] + (dp[p][j - q] * (25 - (s[i] as u64 - 'a' as u64)) % MOD)) % MOD;
                    }
                }
                sum[j] = (sum[j] + dp[i][j]) % MOD;
            }
        }

        println!("{}", sum[k]);
    }
}

