fn main() -> io::Result<()> {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input)?;

    let mut lines = input.lines();
    let n: usize = lines.next().unwrap().parse().unwrap();

    let mut s = Vec::with_capacity(n);
    for _ in 0..n {
        let _ = lines.next().unwrap().chars().next(); // Skip the first character
        s.push(lines.next().unwrap().to_string());
    }

    let mut a = [0; 26];
    let mut b = [[0; 26]; 26];

    for word in s.iter() {
        for (i, ch) in word.chars().enumerate() {
            let index = (ch as u8 - b'a') as usize;
            a[index] += 1;
            if let Some(next_ch) = word.chars().nth(i + 1) {
                let next_index = (next_ch as u8 - b'a') as usize;
                b[index][next_index] += 1;
            }
        }
    }

    for (i, &count) in a.iter().enumerate() {
        if count == 0 {
            println!("{}", (b'a' + i as u8) as char);
            return Ok(());
        }
    }

    for (i, row) in b.iter().enumerate() {
        for (j, &count) in row.iter().enumerate() {
            if count == 0 {
                println!("{}{}", (b'a' + i as u8) as char, (b'a' + j as u8) as char);
                return Ok(());
            }
        }
    }

    Ok(())
}

