fn main() -> io::Result<()> {
    let mut input = String::new();
    io::stdin().read_line(&mut input)?;
    let mut iter = input.split_whitespace();
    let a: usize = iter.next().unwrap().parse().unwrap();
    let b: usize = iter.next().unwrap().parse().unwrap();

    let mut za = String::with_capacity(a);

    match a.cmp(&b) {
        std::cmp::Ordering::Less => za.push_str("-1"),
        std::cmp::Ordering::Equal => {
            for c in 0..a {
                za.push((b'a' as u8 + c as u8) as char);
            }
        }
        std::cmp::Ordering::Greater => {
            if b == 1 {
                za.push_str("-1");
            } else {
                za.push('a');
                let mut c = 1;
                while c < a - b + 2 {
                    za.push('b');
                    za.push('a');
                    c += 2;
                }
                for c in 0..b - 2 {
                    za.push((b'c' as u8 + c as u8) as char);
                }
            }
        }
    }

    writeln!(io::stdout(), "{}", za)
}

