fn main() {
    let stdin = io::stdin();
    let mut lines = stdin.lock().lines();
    if let Some(Ok(n_str)) = lines.next() {
        if let Ok(n) = n_str.parse::<usize>() {
            for _ in 0..n {
                if let Some(Ok(line)) = lines.next() {
                    if let Some(result) = check_string(&line) {
                        println!("{}", result);
                    }
                }
            }
        }
    }
}

fn check_string(s: &str) -> Option<&'static str> {
    if s.len() % 2 != 0 {
        return Some("NO");
    }
    let mid = s.len() / 2;
    for (a, b) in s.chars().take(mid).zip(s.chars().skip(mid)) {
        if a != b {
            return Some("NO");
        }
    }
    Some("YES")
}

