#include <stdio.h>
#define swap(a, b) (a ^= b, b ^= a, a ^= b)
#define max(a, b) ((a) > (b) ? (a) : (b))
#define min(a, b) ((a) < (b) ? (a) : (b))

int main() {
	int t; scanf("%d", &t);
	while (t--) {
		long long n, k, l1, r1, l2, r2;
		scanf("%I64d%I64d%I64d%I64d%I64d%I64d", &n, &k, &l1, &r1, &l2, &r2);
		if (l1 > l2)
			swap(l1, l2), swap(r1, r2);
		if (l2 <= r1)
			if (n * (min(r1, r2) - l2) >= k)
				puts("0");
			else if (n * (max(r1, r2) - l1) >= k)
				printf("%I64d\n", k - n * (min(r1, r2) - l2));
			else
				printf("%I64d\n", n * (max(r1, r2) - min(r1, r2) - l1 + l2)
						+ (k - n * (max(r1, r2) - l1) << 1));
		else
			if (r2 - l1 >= k)
				printf("%I64d\n", l2 - r1 + k);
			else if (n * (r2 - l1) >= k)
				printf("%I64d\n", k / (r2 - l1) * (r2 - r1 + l2 - l1)
						+ min(k % (r2 - l1) << 1, l2 - r1 + k % (r2 - l1)));
			else
				printf("%I64d\n", n * (r2  - r1 + l2 - l1) + (k - n * (r2 - l1) << 1));
	}
	return 0;
}

