        let mut iter = input.split_whitespace().map(|s| s.parse::<i64>().unwrap());
        let n = iter.next().unwrap();
        let k = iter.next().unwrap();
        let mut l1 = iter.next().unwrap();
        let mut r1 = iter.next().unwrap();
        let mut l2 = iter.next().unwrap();
        let mut r2 = iter.next().unwrap();

        if l1 > l2 {
            std::mem::swap(&mut l1, &mut l2);
            std::mem::swap(&mut r1, &mut r2);
        }

        if l2 <= r1 {
            if n * (min(r1, r2) - l2) >= k {
                println!("0");
            } else if n * (max(r1, r2) - l1) >= k {
                println!("{}", k - n * (min(r1, r2) - l2));
            } else {
                println!("{}", n * (max(r1, r2) - min(r1, r2) - l1 + l2) + (k - n * (max(r1, r2) - l1)) * 2);
            }
        } else {
            if r2 - l1 >= k {
                println!("{}", l2 - r1 + k);
            } else if n * (r2 - l1) >= k {
                let quotient = k / (r2 - l1);
                let remainder = k % (r2 - l1);
                println!("{}", quotient * (r2 - r1 + l2 - l1) + min(remainder * 2, l2 - r1 + remainder));
            } else {
                println!("{}", n * (r2 - r1 + l2 - l1) + (k - n * (r2 - l1)) * 2);
            }
        }

        t -= 1;
    }
}

