                            c[i] -= t1;
                            c[j] += t1;
                            min += t1 * arr[i][j];
                        } else {
                            c[i] -= t2;
                            c[j] += t2;
                            min += t2 * arr[i][j];
                        }
                    }
                    t1 = c[i] - n / 3;
                }
            }
        }

