			if ((a & 1 << i) == 0)
				cnt0++;
		for (i = 0; i < n; i++)
			if ((a & 1 << i) > 0)
				for (j = 0; j < n; j++)
					if ((a & 1 << j) == 0)
						ff[a] += ff[a - (1 << i)] * aa[j][i];
		ff[a] /= (cnt0 + 1) * cnt0 / 2;
	}
	for (i = 0; i < n; i++)
		printf("%.6lf ", ff[(1 << n) - 1 - (1 << i)]);
	printf("\n");
	return 0;
}

