    a.push(b[0]);
    a.push(b[0] + b[1]);
    let mut max = a[1];

    for i in 2..n {
        let value = b[i] + max;
        a.push(value);
        if value > max {
            max = value;
        }
    }

    let stdout = io::stdout();
    let mut handle = stdout.lock();
    for (i, &value) in a.iter().enumerate() {
        if i > 0 {
            write!(handle, " ")?;
        }
        write!(handle, "{}", value)?;
    }
    writeln!(handle)?;

    Ok(())
}

