#define N 100000
#define MD 1000000007

int main() {
	static char s[N + 1];
	static int ff[N + 1];
	int n, i, j;
	long long ans;

	scanf("%s", s);
	n = strlen(s);
	ff[0] = ff[1] = 1;
	for (i = 2; i <= n; i++)
		ff[i] = (ff[i - 1] + ff[i - 2]) % MD;
	for (i = 0; i < n; i++)
		if (s[i] == 'w' || s[i] == 'm') {
			printf("0\n");
			return 0;
		}
	ans = 1;
	for (i = 0; i < n; )
		if (s[i] == 'u' || s[i] == 'n') {
			j = i + 1;
			while (j < n && s[j] == s[i])
				j++;
			ans = ans * ff[j - i] % MD;
			i = j;
		} else
			i++;
	printf("%lld\n", ans);
	return 0;
}

