    for i in 0..n - 2 {
        for j in i + 1..n - 1 {
            for k in j + 1..n {
                let (xi, yi) = points[i];
                let (xj, yj) = points[j];
                let (xk, yk) = points[k];
                if (xi * (yj - yk) + xj * (yk - yi) + xk * (yi - yj)) != 0 {
                    triangulos += 1;
                }
            }
        }
    }

    println!("{}", triangulos);
}

