typedef long long ll;

int main ()
{
    int n, m; scanf ("%d%d", &n, &m);
    ll *dplast = (ll *) calloc (m + 1, sizeof (ll));
    ll *dpcurt = (ll *) malloc ((m + 1) * sizeof (ll));
    ll *buf = (ll *) malloc (m * sizeof (ll));
    for (int i = 0; i < n; i++)
    {
        if (i & 1) 
        {
            ll sum = 0;
            for (int j = 0; j < m; j++)
            {
                scanf ("%I64d", buf + j);
                sum += buf[j];
            }
            ll maxlast = dplast[m];
            for (int j = m - 1; j >= 1; j--)
            {
                sum -= buf[j];
                if (dplast[j + 1] > maxlast)
                    maxlast = dplast[j + 1];
                dpcurt[j] = sum + maxlast;
            }
        }
        else 
        {
            ll sum; scanf ("%I64d", &sum);
            ll maxlast = dplast[1];
            for (int j = 2; j <= m; j++)
            {
                ll num; scanf ("%I64d", &num);
                sum += num;
                if (dplast[j - 1] > maxlast)
                    maxlast = dplast[j - 1];
                dpcurt[j] = sum + maxlast;
            }
        }
        {
            ll *t = dplast;
            dplast = dpcurt;
            dpcurt = t;
        }
    }
    ll ans = -1000000000000;
    int start = (n & 1 ? 2 : 1);
    int end = (n & 1 ? m : m - 1);
