    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut lines = input.lines();
    let mut t: i32 = lines.next().unwrap().parse().unwrap();

    while t > 0 {
        let line = lines.next().unwrap();
        let mut parts = line.split_whitespace();
        let n: usize = parts.next().unwrap().parse().unwrap();
        let k: i32 = parts.next().unwrap().parse().unwrap();
        let mut x: i64 = parts.next().unwrap().parse().unwrap();
        let cc: String = parts.next().unwrap().to_string();
        x -= 1;

        let mut bb = vec![0; N];
        let mut cnt = 0;
        let mut i = -1;
        for (j, c) in cc.chars().enumerate() {
            if c == 'a' {
                bb[cnt] = ((j as i32 - i - 1) * k + 1) as usize;
                cnt += 1;
                i = j as i32;
            }
        }
        bb[cnt] = ((n as i32 - i - 1) * k + 1) as usize;
        cnt += 1;

        let mut dd = vec![0; N];
        for h in (0..cnt).rev() {
            dd[h] = (x % bb[h] as i64) as usize;
            x /= bb[h] as i64;
        }

        let mut cc_ = vec![' '; L + 1];
        let mut l = 0;
        for h in 0..cnt {
            for _ in 0..dd[h] {
                cc_[l] = 'b';
                l += 1;
            }
            if h + 1 < cnt {
                cc_[l] = 'a';
                l += 1;
            }
        }
        cc_[l] = '\0';

        let result: String = cc_[..l].iter().collect();
        println!("{}", result);

