int main(void)
{
	int i, t, k, a, b, f[100001], s[100001], mod = 1000000007;

	scanf("%d%d", &t, &k);
	f[0] = 1;
	for (i = 1; i <= 100000; ++i)
		if (i - k >= 0)
			f[i] = (f[i - 1] + f[i - k]) % mod;
		else
			f[i] = f[i - 1];
	s[0] = 0;
	for (i = 1; i <= 100000; ++i)
		s[i] = (s[i - 1] + f[i]) % mod;
	while (t--) {
		scanf("%d%d", &a, &b);
		printf("%d\n", s[b] < s[a - 1] ? s[b] - s[a - 1] + mod : s[b] - s[a - 1]);	
	}

	return 0;
}

