    let mut lines = input.lines();
    let mut first_line = lines.next().unwrap().split_whitespace();
    let t: usize = first_line.next().unwrap().parse().unwrap();
    let k: usize = first_line.next().unwrap().parse().unwrap();

    const MOD: usize = 1_000_000_007;
    let mut f = vec![0; 100001];
    let mut s = vec![0; 100001];
    f[0] = 1;

    for i in 1..=100000 {
        f[i] = if i >= k {
            (f[i - 1] + f[i - k]) % MOD
        } else {
            f[i - 1]
        };
    }

    for i in 1..=100000 {
        s[i] = (s[i - 1] + f[i]) % MOD;
    }

    for _ in 0..t {
        let mut query = lines.next().unwrap().split_whitespace();
        let a: usize = query.next().unwrap().parse().unwrap();
        let b: usize = query.next().unwrap().parse().unwrap();
        let result = if s[b] < s[a - 1] {
            s[b] - s[a - 1] + MOD
        } else {
            s[b] - s[a - 1]
        };
        println!("{}", result);
    }

    Ok(())
