use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let s = input.trim();
    let len = s.len();

    let mut a = vec![0; len + 1];

    a[0] = 0;
    if len > 1 && s.as_bytes()[0] == b'(' && s.as_bytes()[1] == b')' {
        a[1] = 2;
    }

    for i in 2..len {
        if s.as_bytes()[i] == b'(' {
            a[i] = 0;
        } else {
            if s.as_bytes()[i - 1] == b'(' {
                a[i] = a[i - 2] + 2;
            } else {
                let j = i as isize - a[i - 1] as isize - 1;
                if j < 0 || a[i - 1] == 0 || (j >= 0 && s.as_bytes()[j as usize] == b')') {
                    a[i] = 0;
                } else {
                    a[i] = a[i - 1] + if j - 1 >= 0 { a[j as usize - 1] } else { 0 } + 2;
                }
            }
        }
    }

    let mut mx = 0;
    let mut ans = 1;
    for &val in &a {
        if mx < val {
            mx = val;
            ans = 1;
        } else if mx == val {
            ans += 1;
        }
    }

    if mx == 0 {
        println!("0 1");
    } else {
        println!("{} {}", mx, ans);
    }
}

