        for (i = 0; i < strlen(arr) - 1; i++){
            if (i == 0 && arr[i] == arr[i + 1]) dp[0] = 1; 
            else if (arr[i] == arr[i + 1]) dp[i] = dp[i - 1] + 1;
            else if (i != 0) dp[i] = dp[i - 1];

        }
        dp[i] = dp[i - 1];

