        else if (arr[L - 1] == arr[L] && arr[D - 1] != arr[D]) sol = dp[D - 1] - dp[L - 1] + 1;
        else if (arr[L - 1] != arr[L] && arr[D - 1] == arr[D]) sol = dp[D - 1] - dp[L - 1] - 1;
        else if (arr[L - 1] != arr[L] && arr[D - 1] != arr[D]) sol = dp[D - 1] - dp[L - 1];
        printf("%d\n", sol);
