fn main() {
    let stdin = io::stdin();
    let mut lines = stdin.lock().lines().map(|l| l.unwrap());

    let mut arr: Vec<char> = lines.next().unwrap().chars().collect();
    let n = arr.len();
    let mut dp = vec![0; n];

    for i in 0..n - 1 {
        if i == 0 && arr[i] == arr[i + 1] {
            dp[0] = 1;
        } else if arr[i] == arr[i + 1] {
            dp[i] = dp[i - 1] + 1;
        } else if i != 0 {
            dp[i] = dp[i - 1];
        }
    }
    dp[n - 1] = dp[n - 2];

    arr.push('a');

    let num_queries: usize = lines.next().unwrap().parse().unwrap();
    for _ in 0..num_queries {
        let query: Vec<usize> = lines.next().unwrap().split_whitespace()
            .map(|s| s.parse().unwrap()).collect();
        let (l, d) = (query[0] - 1, query[1] - 1);

        let sol = if arr[l] == arr[l + 1] && arr[d] == arr[d + 1] {
            dp[d] - dp[l]
        } else if arr[l] == arr[l + 1] && arr[d] != arr[d + 1] {
            dp[d] - dp[l] + 1
        } else if arr[l] != arr[l + 1] && arr[d] == arr[d + 1] {
            dp[d] - dp[l] - 1
        } else {
            dp[d] - dp[l]
        };
        println!("{}", sol);
    }
}

