#include <stdio.h>
#define MOD 1000000007
int dp[1001][55][1001];
int a[101][1001];
long long fact[101];
int binom[2001][2001];
int main()
{
    for(int i=0;i<=1000;i++)dp[i][0][0]=1;
    for(int add=1;add<=1000;add++)
    {
      for(int len=1;len<=52;len++)
      {
          for(int sum=1;sum<=1000;sum++)
          {
            dp[add][len][sum]=dp[add-1][len][sum];

            if(sum-add>=0)
              {
                dp[add][len][sum]+=dp[add-1][len-1][sum-add];
                if(dp[add][len][sum]>=MOD)dp[add][len][sum]%=MOD;
              }
          }
      }
    }
    for(int len=1;len<=52;len++)
      for(int sum=1;sum<=1000;sum++)
        a[len][sum]=dp[1000][len][sum];

    fact[0]=1;
    for(int i=1;i<=100;i++)fact[i]=(fact[i-1]*i)%MOD;
    for(int i=0;i<=2000;i++)binom[i][0]=1;
    for(int i=1;i<=2000;i++)
      for(int j=1;j<=i;j++)
        binom[i][j]=(binom[i-1][j-1]+binom[i-1][j])%MOD;

    int t;
    scanf("%d",&t);
    while(t--)
    {
      int n,k;
      scanf("%d%d",&n,&k);
      long long sol=0;
      if(k>=51)
      {
        printf("0\n");
      }
      else
      {
        for(int i=1;i<=n;i++)
        {
          sol+=(1LL*(1LL*a[k][i]*1LL*fact[k])%MOD*1LL*binom[n-i+k][k])%MOD;

          sol%=MOD;
        }
        printf("%lld\n",sol);
      }
    }
}

