				continue;
			pp[a * b] += a == b ? (long long) kk[a] * (kk[b] - 1) : (long long) kk[a] * kk[b] * 2LL;
		}
	}
	for (a = 1; a <= A; a++)
		pp[a] += pp[a - 1];
	scanf("%d", &m);
	while (m-- > 0) {
