int main()
{
    int t;
    scanf("%lld",&t);
    for (int k = 0; k < t; k++)
    {
        ll l, h;
        scanf("%lld%lld",&l,&h);
        ll c[h - l + 1];
        ll count = 0;
        for (ll i = 0; i < (h - l + 1); i++)
        {
            c[i] = 0;
        }
        for (ll i = l; i < h; i++)
        {
            for (ll j = 2 * i; j <= h; j += i)
            {
                c[j - l]++;
            }
        }
        for (int i = l; i <= h; i++)
        {
            count = count + ((c[i - l] * (c[i - l] - 1)) / 2);
        }
        ll p = 0;
        for (int i = l; i <= h; i++)
        {
            if (i % 2 == 0 && (2 * i) % 3 == 0 && i / 2 >= l)
                p++;
            if ((2 * i) % 5 == 0 && (2 * i) % 3 == 0 && (2 * i) / 5 >= l)
                p++;
        }
        ll ans;
        ll n;
        n = h - l + 1;
        ans =((n)*(n-1)*(n-2))/6;
        printf("%lld\n",ans - count - p);
    }
    return 0;
}

