        let r = n + m - x;
        let full_groups = r / x;
        let remainder = r % x;
        let cost = 1_i64 * c1 * x as i64
            + 1_i64 * full_groups as i64 * full_groups as i64 * c2 * (x - remainder) as i64
            + 1_i64 * (full_groups + 1) as i64 * (full_groups + 1) as i64 * c2 * remainder as i64;
        if ans == -1 || cost < ans {
            ans = cost;
        }
    }

    println!("{}", ans);
}

