        let actions: Vec<usize> = lines.next().unwrap().split_whitespace()
            .map(|s| s.parse().unwrap()).collect();

        for (j, &act) in actions.iter().enumerate() {
            if act > 0 {
                if top[j] == 0 {
                    ans -= i;
                }
                if left == 0 {
                    ans -= j;
                }
                left = j + 1;
                top[j] = i + 1;
                ans -= 4;
            }
        }
        if left == 0 {
            ans -= m * 2;
        } else {
            ans -= m - left;
        }
    }

    for &height in &top {
        if height == 0 {
            ans -= n * 2;
        } else {
            ans -= n - height;
        }
    }

    println!("{}", ans);
}

