use std::io::{self, BufRead};

fn main() {
    let stdin = io::stdin();
    let mut lines = stdin.lock().lines().map(|l| l.unwrap());

    let n: usize = lines.next().unwrap().parse().unwrap();
    let mut ara: Vec<(i32, i32)> = Vec::with_capacity(n);

    for _ in 0..n {
        let line = lines.next().unwrap();
        let mut parts = line.split_whitespace();
        let x: i32 = parts.next().unwrap().parse().unwrap();
        let y: i32 = parts.next().unwrap().parse().unwrap();
        ara.push((x, y));
    }

    ara.sort_by_key(|&(x, _)| x);

    let negative = ara.iter().take_while(|&&(x, _)| x < 0).count();
    let positive = n - negative;
    let mut count = 0;

    match positive.cmp(&negative) {
        std::cmp::Ordering::Greater => {
            for &(_, y) in ara.iter().take(2 * negative + 1) {
                count += y;
            }
        }
        std::cmp::Ordering::Less => {
            for &(_, y) in ara.iter().rev().take(2 * positive + 1) {
                count += y;
            }
        }
        std::cmp::Ordering::Equal => {
            for &(_, y) in &ara {
                count += y;
            }
        }
    }

    println!("{}", count);
}

