#define MAX_N 1000
#define MAX_M MAX_N

static int _edge[MAX_M], _edge_first[MAX_N], _edge_count[MAX_N] = {};
static bool _leaf[MAX_N] = {};

typedef struct InputEdge { int a, b; } InputEdge;
static InputEdge _input[MAX_M];

int main() {
    int N; scanf("%d\n", &N);
    for(int i = 0, in = N-1 ; i < in ; ++i) {
        int p; scanf("%d\n", &p); --p;
        _input[i].a = p, _input[i].b = i+1; ++_edge_count[p];
    }


    _edge_first[0] = 0;
    for(int i = 1 ; i < N ; ++i)
        _edge_first[i] = _edge_first[i-1] + _edge_count[i-1];


    for(int i = 0 ; i < N-1 ; ++i) { const int a = _input[i].a, b = _input[i].b;
        _edge[_edge_first[a]++] = b;
    }


    for(int i = 0 ; i < N ; ++i)
        _edge_first[i] -= _edge_count[i];


    for(int i = 0 ; i < N ; ++i)
        _leaf[i] = _edge_count[i] == 0;


    bool found = false;
    for(int i = 0 ; i < N && !found ; ++i) {
        if(!_leaf[i]) {

            int count = 0; for(int ei = _edge_first[i], en = ei + _edge_count[i] ; ei < en ; ++ei) {

                if(_leaf[_edge[ei]]) ++count;
            }

