fn main() {
    let stdin = io::stdin();
    let mut lines = stdin.lock().lines().map(|l| l.unwrap());

    let n: usize = lines.next().unwrap().parse().unwrap();
    let mut input = Vec::with_capacity(n - 1);
    for _ in 0..n - 1 {
        let p: usize = lines.next().unwrap().parse().unwrap();
        input.push((p - 1, input.len() + 1));
    }

    let mut edge_count = vec![0; n];
    for &(a, _) in &input {
        edge_count[a] += 1;
    }

    let mut edge_first = vec![0; n];
    for i in 1..n {
        edge_first[i] = edge_first[i - 1] + edge_count[i - 1];
    }

    let mut edge = vec![0; n - 1];
    for &(a, b) in &input {
        edge[edge_first[a]] = b;
        edge_first[a] += 1;
    }

    for i in 0..n {
        edge_first[i] -= edge_count[i];
    }

    let mut leaf = vec![false; n];
    for (i, &count) in edge_count.iter().enumerate() {
        leaf[i] = count == 0;
    }

    let mut found = false;
    for i in 0..n {
        if !leaf[i] {
            let count = edge_first[i]..edge_first[i] + edge_count[i];
            let leaf_count = count.filter(|&ei| leaf[edge[ei]]).count();
            if leaf_count < 3 {
                found = true;
                break;
            }
        }
    }

    println!("{}", if found { "No" } else { "Yes" });
}

