            if ((b & 1) == 1)
            {
                ans += f[b];
                ans %= MOD;
                b--;
            }
            a = (a-1) / 2;
            b = (b-1) / 2;
        }
        if (a == b)
        {
            ans += f[a];
            ans %= MOD;
        }
