fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut lines = input.lines();
    let mut t: i32 = lines.next().unwrap().parse().unwrap();

    let mut c = vec![vec![0; MAXN]; MAXN];
    let mut dp = vec![vec![0; MAXM]; MAXN];
    let mut fac = vec![0; MAXN];

    for i in 0..MAXN {
        c[i][0] = 1;
        if i > 0 {
            c[i][i] = 1;
        }
        for j in 1..i {
            c[i][j] = (c[i - 1][j - 1] + c[i - 1][j]) % MOD;
        }
    }

    dp[0][0] = 1;
    for i in 1..MAXN {
        for j in 0..MAXM {
            for k in (i..=j).step_by(i) {
                dp[i][j] = (dp[i][j] + dp[i - 1][j - k]) % MOD;
            }
        }
    }

    fac[0] = 1;
    for i in 1..MAXN {
        fac[i] = (i as u64 * fac[i - 1]) % MOD;
    }

    while t > 0 {
        let nk: Vec<&str> = lines.next().unwrap().split_whitespace().collect();
        let n: usize = nk[0].parse().unwrap();
