        for i in 0..n {
            if n - 1 - i >= k - 1 {
                res = (res + dp[k][i + k] as u64 * c[n - i][n - i - k]) % MOD;
            }
        }
        res = (res * fac[k] as u64) % MOD;
        println!("{}", res);

        t -= 1;
    }
}

