	int t, n, k, f, a;

	dp[0][0] = 1;
	for (k = 1; k <= K; k++)
		for (n = 1; n <= N; n++) {
			int m, x = 0;

			for (a = 1; (m = n - a * k) >= 0; a++)
				x = (x + dp[k - 1][m]) % MD;
			dp[k][n] = x;
		}
	for (k = 0, f = 1; k <= K; k++) {
		ff[k] = f;
		f = (long long) f * (k + 1) % MD;
	}
	ch[0][0] = 1;
	for (n = 1; n <= N; n++) {
		ch[n][0] = 1;
		for (k = 1; k <= K; k++)
			ch[n][k] = (ch[n - 1][k] + ch[n - 1][k - 1]) % MD;
	}
