fn process_number(mut n: i64) -> String {
    let mut cnt = 0;
    while n != 1 {
        match (n % 2, n % 3, n % 5) {
            (0, _, _) => n /= 2,
            (_, 0, _) => n = (n * 2) / 3,
            (_, _, 0) => n = (n * 4) / 5,
            _ => return "-1".to_string(),
        }
        cnt += 1;
    }
    cnt.to_string()
}

