            if (arr[i - 1] > maxes[i])
                maxes[i] = arr[i - 1];
        }
        mins[n] = -1;
        for (unsigned int i = n - 1; i < n; --i) {
            mins[i] = mins[i + 1];
            if (arr[i] < mins[i])
                mins[i] = arr[i];
        }
        bool can_not_sort = false;
        for (unsigned int i = 1; i <= n - 1; ++i) {
            if (maxes[i] > mins[i]) {
                can_not_sort = true;
                break;
            }
        }
        puts(can_not_sort ? "YES" : "NO");
        free(arr);
        free(maxes);
