    for i in k + 1..N {
        dp[i] = (dp[i - k] + dp[i - 1]) % MOD;
    }

    let mut sum = vec![0; N];
    let mut sum_all = 0;
    for i in 1..N {
        sum_all = (sum_all + dp[i]) % MOD;
        sum[i] = sum_all;
    }

