fn main() {
    let mut input = String::new();
    io::stdin().read_line(&mut input).unwrap();
    let mut iter = input.split_whitespace().map(|s| s.parse::<i32>().unwrap());
    let n = iter.next().unwrap();
    let k = iter.next().unwrap();
    let _l = iter.next().unwrap();
    let _r = iter.next().unwrap();
    let sall = iter.next().unwrap();
    let sk = iter.next().unwrap();

    let mut ans = vec![sk / k; k as usize];
    for i in 0..(sk % k) {
        ans[i as usize] += 1;
    }

    if n != k {
        let remaining_sum = sall - sk;
        let remaining_count = n - k;
        let base_value = remaining_sum / remaining_count;
        ans.extend(std::iter::repeat(base_value).take(remaining_count as usize));
        for i in 0..(remaining_sum % remaining_count) {
            ans[(k + i) as usize] += 1;
        }
    }

    let mut output = ans.iter().map(|x| x.to_string()).collect::<Vec<_>>().join(" ");
    output.push('\n');
    io::stdout().write_all(output.as_bytes()).unwrap();
}

