        let after: u16 = parts.next().unwrap().parse().unwrap();
        ratings.push(Rating { before, after });
    }

    for rating in &ratings {
        if rating.before != rating.after {
            println!("rated");
            return;
        }
    }

    for i in 0..ratings.len() - 1 {
        if ratings[i].before < ratings[i + 1].before {
            println!("unrated");
            return;
        }
    }

    println!("maybe");
}

