fn main() {
    let stdin = io::stdin();
    let mut lines = stdin.lock().lines().map(|l| l.unwrap());

    let first_line: Vec<i32> = lines.next().unwrap().split_whitespace().map(|s| s.parse().unwrap()).collect();
    let (n, k, q) = (first_line[0] as usize, first_line[1] as usize, first_line[2] as usize);

    let mut t = vec![0; n + 1];
    for (i, line) in lines.by_ref().take(n).enumerate() {
        t[i + 1] = line.parse().unwrap();
    }

    let mut online = vec![Node::default(); k];

