                need[b[i]]++;
                node *t=calloc(1,sizeof(node));
                t->ind=i;
                t->next=loc[b[i]];
                loc[b[i]]=t;
            }
        }
        for(int i=1;i<=m;i++)scanf("%d",&c[i]);
        int last=0;
        int flag=1;
        for(int i=m;i;i--){
            if(need[c[i]]){
                ans[i]=loc[c[i]]->ind;
                if(--need[c[i]]==0)tot--;
                node *t=loc[c[i]];
                loc[c[i]]=loc[c[i]]->next;
                free(t);
            }
            else{
                if(last==0){
                    if(ex[c[i]]){
                        ans[i]=ex[c[i]];
                    }
                    else {
                        printf("NO\n");
                        flag=0;
                        break;
                    }
                }
                else ans[i]=last;
            }
            last=ans[i];
