use std::collections::HashMap;

fn main() {
    let mut input = String::new();
    std::io::stdin().read_line(&mut input).unwrap();
    let mut t: i32 = input.trim().parse().unwrap();
    while t > 0 {
        input.clear();
        std::io::stdin().read_line(&mut input).unwrap();
        let mut parts = input.split_whitespace();
        let n: usize = parts.next().unwrap().parse().unwrap();
        let m: usize = parts.next().unwrap().parse().unwrap();

        let mut a = vec![0; n + 1];
        let mut b = vec![0; n + 1];
        let mut need = vec![0; n + 1];
        let mut ex = HashMap::new();
        let mut loc = vec![Vec::new(); n + 1];
        let mut tot = 0;

        input.clear();
        std::io::stdin().read_line(&mut input).unwrap();
        parts = input.split_whitespace();
        for i in 1..=n {
            a[i] = parts.next().unwrap().parse().unwrap();
        }

        input.clear();
        std::io::stdin().read_line(&mut input).unwrap();
        parts = input.split_whitespace();
        for i in 1..=n {
            b[i] = parts.next().unwrap().parse().unwrap();
            ex.insert(b[i], i);
            if a[i] != b[i] {
                if need[b[i]] == 0 {
                    tot += 1;
                }
                need[b[i]] += 1;
                loc[b[i]].push(i);
            }
        }

        let mut c = vec![0; m + 1];
        input.clear();
        std::io::stdin().read_line(&mut input).unwrap();
        parts = input.split_whitespace();
        for i in 1..=m {
            c[i] = parts.next().unwrap().parse().unwrap();
        }

        let mut ans = vec![0; m + 1];
        let mut last = 0;
        let mut flag = true;

        for i in (1..=m).rev() {
            if need[c[i]] > 0 {
                ans[i] = loc[c[i]].pop().unwrap();
                need[c[i]] -= 1;
                if need[c[i]] == 0 {
                    tot -= 1;
                }
            } else {
                if last == 0 {
                    if let Some(&index) = ex.get(&c[i]) {
                        ans[i] = index;
                    } else {
                        println!("NO");
                        flag = false;
                        break;
                    }
                } else {
                    ans[i] = last;
                }
            }
            last = ans[i];
        }

        if flag && tot > 0 {
            println!("NO");
        } else if flag {
            println!("YES");
            for i in 1..=m {
                print!("{} ", ans[i]);
            }
            println!();
        }

        t -= 1;
