struct Node {
    id: i32,
    t: i32,
}

fn main() {
    let stdin = io::stdin();
    let mut lines = stdin.lock().lines().map(|l| l.unwrap());

    let first_line: Vec<i32> = lines.next().unwrap().split_whitespace().map(|s| s.parse().unwrap()).collect();
    let (n, k, q) = (first_line[0] as usize, first_line[1] as usize, first_line[2] as usize);

    let mut t = vec![0; n + 1];
    for (i, line) in lines.by_ref().take(n).enumerate() {
        t[i + 1] = line.parse().unwrap();
    }

    let mut online = vec![Node::default(); k];

    for _ in 0..q {
        let query_line: Vec<i32> = lines.next().unwrap().split_whitespace().map(|s| s.parse().unwrap()).collect();
        let (query, id) = (query_line[0], query_line[1]);

        if query == 1 {
            if let Some(slot) = online.iter_mut().find(|node| node.id == 0) {
                *slot = Node { id, t: t[id as usize] };
            } else {
                let (min_pos, &min_node) = online.iter().enumerate().min_by_key(|&(_, node)| node.t).unwrap();
                if t[id as usize] > min_node.t {
                    online[min_pos] = Node { id, t: t[id as usize] };
                }
            }
        } else {
            if online.iter().any(|node| node.id == id) {
                println!("YES");
            } else {
                println!("NO");
            }
        }
    }
}

