fn main() -> io::Result<()> {
    let mut input = String::new();
    io::stdin().read_line(&mut input)?;
    let mut q: i32 = input.trim().parse().unwrap();

    let mut output = Vec::new();

    while q > 0 {
        input.clear();
        io::stdin().read_line(&mut input)?;
        let mut iter = input.trim().split_whitespace();
        let w: i32 = iter.next().unwrap().parse().unwrap();
        let e: i32 = iter.next().unwrap().parse().unwrap();

        let r = if w < e { w } else { e };
        let w = w - r;
        let e = e - r;

        output.extend(std::iter::repeat("01").take(r as usize).flat_map(|s| s.bytes()));
        output.extend(std::iter::repeat(b'0').take(w as usize));
        output.extend(std::iter::repeat(b'1').take(e as usize));
        output.push(b'\n');

        q -= 1;
    }

    io::stdout().write_all(&output)?;
    Ok(())
}

