    let a: Vec<usize> = lines.take(n).collect();

    let mut dp = vec![0; 5001];
    for &value in &a {
        dp[value] += 1;
    }

    let mut min = usize::MAX;
    for i in 1..=n {
        if dp[i] > 0 {
            let sum: usize = dp.iter().enumerate()
                .filter(|&(j, _)| j < i || j > 2 * i)
                .map(|(_, &count)| count)
                .sum();
            if sum < min {
                min = sum;
            }
        }
    }

