fn main() {
    let stdin = io::stdin();
    let mut lines = stdin.lock().lines();

    let t: usize = lines.next().unwrap().unwrap().parse().unwrap();
    for _ in 0..t {
        let size: usize = lines.next().unwrap().unwrap().parse().unwrap();
        let arr: Vec<i32> = lines.next().unwrap().unwrap()
            .split_whitespace()
            .map(|s| s.parse().unwrap())
            .collect();

        let (odd, even) = arr.iter().fold((0, 0), |(odd, even), &num| {
            if num % 2 != 0 {
                (odd + 1, even)
            } else {
                (odd, even + 1)
            }
        });

        if even == size || (odd == size && odd % 2 == 0) {
            println!("No");
        } else {
            println!("Yes");
        }
    }
}

