            print!("{} ", n + 1);
            for i in 1..=n {
                print!("{} ", i);
            }
            println!();
            continue;
        }
        if elements[n] == 0 {
            for i in 1..=n + 1 {
                print!("{} ", i);
            }
            println!();
            continue;
        }
        let mut check = false;
        for i in 1..n {
            if elements[i] == 0 && elements[i + 1] == 1 {
                for j in 1..=i {
                    print!("{} ", j);
                }
                print!("{} ", n + 1);
                for j in i + 1..=n {
                    print!("{} ", j);
                }
                println!();
                check = true;
                break;
            }
        }
        if !check {
            println!("-1");
        }
