use std::io::{self, Write};

fn main() -> io::Result<()> {
    let mut input = String::new();
    io::stdin().read_line(&mut input)?;
    let size: usize = input.trim().parse().expect("Please enter a valid number");

    let mut arr = Vec::with_capacity(size);
    for _ in 0..size {
        input.clear();
        io::stdin().read_line(&mut input)?;
        let num: i32 = input.trim().parse().expect("Please enter a valid number");
        arr.push(num);
    }

    let mut stdout = io::stdout();
    writeln!(stdout, "{} {}", arr[1] - arr[0], arr[size - 1] - arr[0])?;

    for i in 1..size - 1 {
        let min_diff = if arr[i + 1] - arr[i] > arr[i] - arr[i - 1] {
            arr[i] - arr[i - 1]
        } else {
            arr[i + 1] - arr[i]
        };
        let max_diff = if arr[i] - arr[0] > arr[size - 1] - arr[i] {
            arr[i] - arr[0]
        } else {
            arr[size - 1] - arr[i]
        };
        writeln!(stdout, "{} {}", min_diff, max_diff)?;
    }

    writeln!(stdout, "{} {}", arr[size - 1] - arr[size - 2], arr[size - 1] - arr[0])?;
    Ok(())
}

