fn main() {
    let stdin = io::stdin();
    let mut lines = stdin.lock().lines();

    if let Some(Ok(n_str)) = lines.next() {
        if let Ok(n) = n_str.parse::<usize>() {
            for _ in 0..n {
                if let Some(Ok(line)) = lines.next() {
                    let parts: Vec<&str> = line.split_whitespace().collect();
                    if parts.len() == 3 {
                        if let (Ok(a), Ok(b), Ok(c)) = (
                            parts[0].parse::<i64>(),
                            parts[1].parse::<i64>(),
                            parts[2].parse::<i64>(),
                        ) {
                            let mut flag = false;

                            if b != 0 && c != 0 {
                                if a == 0 && b == 0 && c == 0 {
                                    flag = true;
                                }

                                let y = c - b;
                                let a0 = b - y;

                                if a0 % a == 0 && a0 > 0 && a > 0 && !flag {
                                    flag = true;
                                }

                                let y = b - a;
                                let c0 = b + y;

                                if c0 % c == 0 && c0 > 0 && !flag {
                                    flag = true;
                                }

                                let y = c + a;

                                if y % (2 * b) == 0 && !flag {
                                    flag = true;
                                }
                            }

                            if flag {
                                println!("YES");
                            } else {
                                println!("NO");
                            }
                        }
                    }
                }
            }
        }
    }
}

