    char ch = 0;
    int no_wait = 0;
    int people = 0;
    int symbols = 0;
    int total = 0;
    while(1) {
        ch = getchar();
        if (ch != -1)
        {
            switch (ch) {
                case '+':
                    {
                        people++;
                        no_wait = 0;
                        break;
                    }
                case '-':
                    {
                        people--;
                        no_wait = 0;
                        break;
                    }
                case ':':
                    {
                        no_wait = 1;
                        break;
                    }
                case '\n':
                    {
                        if (no_wait){
                            total += (symbols - 1) * people;
                            symbols = 0;
                            no_wait = 0;
                            break;
                        }
                    }
            }
        }
        else
            break;
        if (no_wait) {
            symbols++;
        } 
    }
    printf("%i", total);
    return 0;
}

