use std::io::{self, Read};

fn main() -> io::Result<()> {
    let mut ch = [0; 1];
    let mut no_wait = false;
    let mut people = 0;
    let mut symbols = 0;
    let mut total = 0;
    let stdin = io::stdin();
    let mut handle = stdin.lock();

    while handle.read(&mut ch)? > 0 {
        match ch[0] as char {
            '+' => {
                people += 1;
                no_wait = false;
            }
            '-' => {
                people -= 1;
                no_wait = false;
            }
            ':' => {
                no_wait = true;
            }
            '\n' => {
                if no_wait {
                    total += (symbols - 1) * people;
                    symbols = 0;
                    no_wait = false;
                }
            }
            _ => {
                if no_wait {
                    symbols += 1;
                }
            }
        }
    }

    println!("{}", total);
    Ok(())
}

