use std::io::{self, Read};

fn main() -> io::Result<()> {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input)?;

    let mut lines = input.lines();
    let n: usize = lines.next().and_then(|s| s.parse().ok()).ok_or(io::Error::new(io::ErrorKind::InvalidInput, "Invalid number of elements"))?;

    if n < 1 || n > 200000 {
        return Err(io::Error::new(io::ErrorKind::InvalidInput, "Number of elements out of bounds"));
    }

    let mut sum_total: u32 = 0;
    let mut sum_part = Vec::with_capacity(n);

    for line in lines.take(n) {
        let a: u16 = line.parse().ok().ok_or(io::Error::new(io::ErrorKind::InvalidInput, "Invalid element value"))?;

        if a < 1 || a > 10000 {
            return Err(io::Error::new(io::ErrorKind::InvalidInput, "Element value out of bounds"));
        }

        sum_total += a as u32;
        sum_part.push(sum_total);
    }

    let half_of_total = if sum_total % 2 == 0 { sum_total / 2 } else { sum_total / 2 + 1 };
    let found_ans = sum_part.iter().position(|&x| x >= half_of_total);

    match found_ans {
        Some(i) => println!("{}", i + 1),
        None => return Err(io::Error::new(io::ErrorKind::Other, "No valid partition found")),
    }

    Ok(())
}

