use std::io::{self, BufRead};

struct Prefix {
    s: String,
}

struct Suffix {
    s: String,
}

fn main() {
    let stdin = io::stdin();
    let mut lines = stdin.lock().lines().map(|l| l.unwrap());

    let first_line: Vec<usize> = lines.next().unwrap().split_whitespace()
        .map(|s| s.parse().unwrap())
        .collect();
    let n = first_line[0];
    let m = first_line[1];

    let mut prefixes: Vec<Prefix> = Vec::with_capacity(n);
    for _ in 0..n {
        let line = lines.next().unwrap();
        prefixes.push(Prefix { s: line });
    }

    let mut suffixes: Vec<Suffix> = Vec::with_capacity(m);
    for _ in 0..m {
        let line = lines.next().unwrap();
        suffixes.push(Suffix { s: line });
    }

    let q: usize = lines.next().unwrap().parse().unwrap();
    let mut queries: Vec<usize> = Vec::with_capacity(q);
    for _ in 0..q {
        let line = lines.next().unwrap();
        queries.push(line.parse().unwrap());
    }

    for &l in &queries {
        let j = if l % n == 0 { n - 1 } else { l % n - 1 };
        let k = if l % m == 0 { m - 1 } else { l % m - 1 };
        println!("{}{}", prefixes[j].s, suffixes[k].s);
    }
}

