use std::cmp;
use std::io::{self, BufRead};

fn main() {
    let stdin = io::stdin();
    let mut lines = stdin.lock().lines().map(|l| l.unwrap());

    let n: usize = lines.next().unwrap().parse().unwrap();
    let mut rooms = Vec::with_capacity(n);
    for _ in 0..n {
        let line = lines.next().unwrap();
        let parts: Vec<i32> = line.split_whitespace().map(|s| s.parse().unwrap()).collect();
        let (l, w, h) = (parts[0], parts[1], parts[2]);
        rooms.push((2 * (l + w), h));
    }

    let m: usize = lines.next().unwrap().parse().unwrap();
    let mut wallpapers = Vec::with_capacity(m);
    for _ in 0..m {
        let line = lines.next().unwrap();
        let parts: Vec<i32> = line.split_whitespace().map(|s| s.parse().unwrap()).collect();
        let (l, w, c) = (parts[0], parts[1], parts[2]);
        wallpapers.push((l, w, c));
    }

    let mut total_cost = 0;
    for &(p, h) in &rooms {
        let mut min_cost = i32::MAX;
        for &(l, w, c) in &wallpapers {
            if l > 0 {
                let a = (l / h) * w;
                if a > 0 {
                    let cost = c * ((p + a - 1) / a);
                    min_cost = cmp::min(min_cost, cost);
                }
            }
        }
        total_cost += min_cost;
    }

    println!("{}", total_cost);
}

