    let n: usize = lines.next().unwrap().parse().unwrap();
    let mut c: Vec<usize> = Vec::with_capacity(n);
    let mut m = 0;

    for _ in 0..n {
        let count: usize = lines.next().unwrap().parse().unwrap();
        c.push(count);
        m += count;
    }

    let mut a: Vec<i32> = Vec::with_capacity(m);
    let mut ii: Vec<Index> = Vec::with_capacity(m);

    for (i, &count) in c.iter().enumerate() {
        for j in 0..count {
            let value: i32 = lines.next().unwrap().parse().unwrap();
            a.push(value);
            ii.push(Index { x: i + 1, y: j + 1 });
        }
    }

    let mut ss: Vec<Swap> = Vec::with_capacity(m);
    let mut k = 0;

    for i in 0..m {
        let mut min = a[i];
        let mut jmin = i;

        for j in (i + 1)..m {
            if a[j] < min {
                jmin = j;
                min = a[j];
            }
        }

        if jmin != i {
            ss.push(Swap {
                x: ii[i].x,
                y: ii[i].y,
                p: ii[jmin].x,
                q: ii[jmin].y,
            });
            a.swap(i, jmin);
            ii.swap(i, jmin);
            k += 1;
        }
    }

    println!("{}", k);
    for swap in &ss {
        println!("{} {} {} {}", swap.x, swap.y, swap.p, swap.q);
    }
}

