        let n: i64 = lines.next().unwrap().unwrap().parse().unwrap();
        let result = process_number(n);
        println!("{}", result);
    }
}

fn process_number(mut n: i64) -> i32 {
    let mut k = 0;
    while n != 1 {
        match n {
            _ if n % 2 == 0 => { n /= 2; k += 1; }
            _ if n % 3 == 0 => { n = (n * 2) / 3; k += 1; }
            _ if n % 5 == 0 => { n = (n * 4) / 5; k += 1; }
            1 => return k,
            _ => return -1,
        }
    }
    k
}

