#include<stdlib.h>
#define maxn (100000+10)
int a[maxn],b[maxn];
int need[maxn],ex[maxn];
int c[maxn];
int ans[maxn];
typedef struct N{
    int ind;
    struct N*next;
}node;
node *loc[maxn];
int tot;
int main(void){
    int t;
    scanf("%d",&t);
    while(t--){
        int n,m;
        scanf("%d%d",&n,&m);
        for(int i=1;i<=n;i++)loc[i]=NULL;
        memset(need,0,sizeof(need));
        tot=0;
        memset(ex,0,sizeof(ex));
        for(int i=1;i<=n;i++)scanf("%d",&a[i]);
        for(int i=1;i<=n;i++){
            scanf("%d",&b[i]);
            ex[b[i]]=i;
            if(a[i]!=b[i]){
                if(need[b[i]]==0)tot++;
                need[b[i]]++;
                node *t=calloc(1,sizeof(node));
                t->ind=i;
                t->next=loc[b[i]];
                loc[b[i]]=t;
            }
        }
        for(int i=1;i<=m;i++)scanf("%d",&c[i]);
        int last=0;
        int flag=1;
        for(int i=m;i;i--){
            if(need[c[i]]){
                ans[i]=loc[c[i]]->ind;
                if(--need[c[i]]==0)tot--;
                node *t=loc[c[i]];
                loc[c[i]]=loc[c[i]]->next;
                free(t);
            }
            else{
                if(last==0){
                    if(ex[c[i]]){
                        ans[i]=ex[c[i]];
                    }
                    else {
                        printf("NO\n");
                        flag=0;
                        break;
                    }
                }
                else ans[i]=last;
            }
            last=ans[i];
        }
        if(flag&&tot)printf("No\n");
        else if(flag){
            printf("YES\n");
            for(int i=1;i<=m;i++)printf("%d ",ans[i]);
            putchar('\n');
        }
    }
    return 0;
}

