        for i in (1..=m).rev() {
            if need[c[i]] > 0 {
                ans[i] = loc[c[i]].pop().unwrap();
                need[c[i]] -= 1;
                if need[c[i]] == 0 {
                    tot -= 1;
                }
            } else {
                if last == 0 {
                    if let Some(&index) = ex.get(&c[i]) {
                        ans[i] = index;
                    } else {
                        println!("NO");
                        flag = false;
                        break;
                    }
                } else {
                    ans[i] = last;
                }
            }
            last = ans[i];
        }

        if flag && tot > 0 {
            println!("NO");
        } else if flag {
            println!("YES");
            for i in 1..=m {
                print!("{} ", ans[i]);
            }
            println!();
        }

        t -= 1;
    }
}

