    let n: usize = lines.next().unwrap().unwrap().parse().unwrap();
    let mut obj: Vec<NameScore> = Vec::with_capacity(n);
    let mut obj1: Vec<Winner> = Vec::with_capacity(n);

    for _ in 0..n {
        let line = lines.next().unwrap().unwrap();
        let parts: Vec<&str> = line.split_whitespace().collect();
        let name = parts[0].to_string();
        let score: i32 = parts[1].parse().unwrap();
        obj.push(NameScore { name, score, score1: score });
    }

    let mut name_map: HashMap<String, i32> = HashMap::new();
    for entry in &mut obj {
        let count = name_map.entry(entry.name.clone()).or_insert(0);
        *count += entry.score;
        entry.score1 = -10000;
    }

    for entry in &mut obj {
        if let Some(&total_score) = name_map.get(&entry.name) {
            entry.score = total_score;
        }
    }

    let max_score = obj.iter().filter(|e| e.score1 != -10000).map(|e| e.score).max().unwrap_or(0);

