use std::io::{self, Write, BufRead, BufReader};

fn main() -> io::Result<()> {
    let file_in = File::open("input.txt")?;
    let file_out = File::create("output.txt")?;
    let mut reader = BufReader::new(file_in);
    let mut writer = file_out;

    let mut door = String::new();
    let mut rail = String::new();

    reader.read_line(&mut door)?;
    reader.read_line(&mut rail)?;

    let door = door.trim();
    let rail: i32 = rail.trim().parse().unwrap_or(0);

    let direction = match (door, rail) {
        ("front", 1) => "L",
        ("front", _) => "R",
        (_, 1) => "R",
        _ => "L",
    };

    writeln!(writer, "{}", direction)?;

    Ok(())
}

