#define SIZE (5 + (4 + 30) * 5000)

int
main(void)
{
	char *in;
	char *current;
	char *board;
	int cases;
	int w, h;
	int wmin, hmin;
	int i, j;

	in = malloc(SIZE);
	current = in;
	fread(in, 1, SIZE, stdin);

	cases = 0;
	while (*current != '\n')
		cases = cases * 10 + *(current++) - '0';
	current++;

	while (cases--) {
		h = *(current + 0) - '0';
		w = *(current + 2) - '0';
		current += 4;
		board = current;
		wmin = w;
		hmin = h;

		for (i = 0; i < h; ++i) {
			for (j = 0; j < w; ++j) {
				if (i >= hmin && j >= wmin) {
					current += w - j;
					break;
				}
				if (*current == 'R') {
					if (j < wmin)
						wmin = j;
					if (i < hmin)
						hmin = i;
				}
				current++;
			}
			current++;
		}
		if (*(board + wmin + hmin*(w+1)) == 'R')
			printf("YES\n");
		else
			printf("NO\n");
	}

	free(in);
	return 0;
}

