    while let Some(Ok(line)) = lines.next() {
        let mut parts = line.split_whitespace();
        let tree: usize = parts.next().unwrap().parse().unwrap();
        let capacity: i32 = parts.next().unwrap().parse().unwrap();

        let mut ara: Vec<TreeInf> = Vec::with_capacity(tree);
        for _ in 0..tree {
            let line = lines.next().unwrap().unwrap();
