            let fruit: i32 = parts.next().unwrap().parse().unwrap();
            ara.push(TreeInf { day, fruit });
        }

        ara.sort_by_key(|x| x.day);

        let mut ans = 0;
        let mut j = 0;
        for i in 1..=ara[tree - 1].day + 1 {
            let mut collected_fruit = 0;
            while j < tree && ara[j].day < i - 1 {
                j += 1;
            }
            while collected_fruit < capacity && j < tree && ara[j].day <= i {
                if capacity - collected_fruit >= ara[j].fruit {
                    collected_fruit += ara[j].fruit;
                    ara[j].fruit = 0;
                } else {
                    ara[j].fruit -= capacity - collected_fruit;
                    collected_fruit = capacity;
                }
                if ara[j].fruit == 0 {
                    j += 1;
                }
            }
            ans += collected_fruit;
        }

        println!("{}", ans);
    }
