        .map(|s| s.parse().unwrap())
        .collect();
    let n = first_line[0];
    let m = first_line[1];

    let mut prefixes: Vec<Prefix> = Vec::with_capacity(n);
    for _ in 0..n {
        let line = lines.next().unwrap();
        prefixes.push(Prefix { s: line });
