    for _ in 0..q {
        let line = lines.next().unwrap();
        queries.push(line.parse().unwrap());
    }

    for &l in &queries {
        let j = if l % n == 0 { n - 1 } else { l % n - 1 };
        let k = if l % m == 0 { m - 1 } else { l % m - 1 };
        println!("{}{}", prefixes[j].s, suffixes[k].s);
    }
