        reader.read_line(&mut line)?;
        a.push(line.trim().parse().unwrap());
    }

    for i in 1..k {
        for j in 0..k - i {
            if a[j] > a[j + 1] {
                a.swap(j, j + 1);
                b.swap(j, j + 1);
            }
        }
    }

    writeln!(writer, "{}", a[k - n])?;

    for i in k - n + 1..k {
        for j in k - n..k - i {
            if b[j] > b[j + 1] {
                b.swap(j, j + 1);
            }
        }
    }

    for i in k - n..k {
