use std::io::{self, BufRead};

#[derive(Debug)]
struct Server {
    name: String,
    ip: String,
}

fn main() {
    let stdin = io::stdin();
    let mut lines = stdin.lock().lines().map(|l| l.unwrap());

    let first_line: Vec<usize> = lines.next().unwrap().split_whitespace()
        .map(|s| s.parse().unwrap())
        .collect();
    let n = first_line[0];
    let m = first_line[1];

    let mut a1: Vec<Server> = Vec::with_capacity(n);
    let mut a2: Vec<Server> = Vec::with_capacity(m);

    for _ in 0..n {
        let name = lines.next().unwrap();
        let mut ip = lines.next().unwrap();
        ip.push(';');
        a1.push(Server { name, ip });
    }

    for _ in 0..m {
        let name = lines.next().unwrap();
        let ip = lines.next().unwrap();
        let mut server = Server { name, ip };
        if let Some(matched_server) = a1.iter().find(|s| s.ip == server.ip) {
            server.ip.push_str(" #");
            server.ip.push_str(&matched_server.name);
        }
        a2.push(server);
    }

    for server in a2 {
        println!("{} {}", server.name, server.ip);
    }
}

