        }

        fa |= a;
    }

    let mut fb = 0;
    for _ in 0..n {
        let b: u32 = match lines.next() {
            Some(Ok(line)) => line.parse().map_err(|_| io::Error::new(io::ErrorKind::InvalidInput, "Invalid number"))?,
