    let mut n: i32 = parts.next().unwrap().parse().unwrap();

    let mut found = false;
    let mut digit = 0;
    for i in 0..10 {
        if (a * 10 + i) % b == 0 {
            found = true;
            digit = i;
            n -= 1;
            break;
        }
    }

    let mut output = io::stdout();
    if !found {
        writeln!(output, "-1")?;
    } else {
        write!(output, "{}{}", a, digit)?;
        for _ in 0..n {
            write!(output, "0")?;
        }
        writeln!(output)?;
    }

    Ok(())
}

