use std::io::{self, BufRead};

fn main() -> io::Result<()> {
    let stdin = io::stdin();
    let mut lines = stdin.lock().lines();

    let n: usize = lines.next().unwrap()?.parse().map_err(|_| io::Error::new(io::ErrorKind::InvalidInput, "Invalid number"))?;
    if n < 1 || n > 100000 {
        return Err(io::Error::new(io::ErrorKind::InvalidInput, "n out of bounds"));
    }

    let mut s = vec![0; n];
    let mut cs = 0;
    let mut csx = 0;
    let ns = 2 * n;

    for _ in 0..ns {
        let x: usize = lines.next().unwrap()?.parse().map_err(|_| io::Error::new(io::ErrorKind::InvalidInput, "Invalid number"))?;
        if x < 1 || x > n {
            return Err(io::Error::new(io::ErrorKind::InvalidInput, "x out of bounds"));
        }
        let xm = x - 1;
        if s[xm] == 2 {
            return Err(io::Error::new(io::ErrorKind::InvalidInput, "Duplicate entry"));
        }
        s[xm] += 1;
        if s[xm] == 1 {
            cs += 1;
        } else {
            if cs > csx {
                csx = cs;
            }
            cs -= 1;
        }
    }

    println!("{}", csx);
