fn main() -> io::Result<()> {
    let input_file = File::open("input.txt")?;
    let mut reader = BufReader::new(input_file);
    let mut n = 0;
    let mut m = 0;

    for _ in 0..2 {
        let mut line = String::new();
        reader.read_line(&mut line)?;
        let parts: Vec<&str> = line.split_whitespace().collect();
        n = parts[0].parse().unwrap_or(90);
        m = parts[1].parse().unwrap_or(100);
    }

    let output_file = File::create("output.txt")?;
    let mut writer = output_file;

    let (mut boys, mut girls) = if n > m { (n, m) } else { (m, n) };
    let mut output = String::with_capacity((n + m) as usize);

    while boys > 0 || girls > 0 {
        if boys > 0 {
            output.push('B');
            boys -= 1;
        }
        if girls > 0 {
            output.push('G');
            girls -= 1;
        }
    }

    writer.write_all(output.as_bytes())?;
    Ok(())
}

