use std::io::{self, Read};

struct Road {
    a: i32,
    b: i32,
    c: i32,
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut lines = input.lines();
    let n: usize = lines.next().unwrap().parse().unwrap();
    let mut roads: Vec<Road> = Vec::with_capacity(n);
    let mut sum = 0;
    for _ in 0..n {
        let parts: Vec<i32> = lines.next().unwrap().split_whitespace().map(|s| s.parse().unwrap()).collect();
        let road = Road { a: parts[0], b: parts[1], c: parts[2] };
        sum += road.c;
        roads.push(road);
    }
    let mut used = vec![false; n];
    let mut cost = 0;
    let mut a = 1;
    loop {
        let mut next = None;
        for (i, road) in roads.iter_mut().enumerate() {
            if road.a == a && !used[i] {
                next = Some((road.b, i));
                break;
            }
        }
        if let Some((b, i)) = next {
            used[i] = true;
            a = b;
        } else {
            let mut found = false;
            for (i, road) in roads.iter_mut().enumerate() {
                if road.b == a && !used[i] {
                    cost += road.c;
                    std::mem::swap(&mut road.a, &mut road.b);
                    a = road.b;
                    used[i] = true;
                    found = true;
                    break;
                }
            }
            if !found {
                break;
            }
        }
    }
    let result = cost.min(sum - cost);
    println!("{}", result);
}

